import { create } from 'zustand';
import { Canvas, FabricObject } from 'fabric';
import { RefObject } from 'react';
import { v4 as uuidv4 } from 'uuid';

interface AnchorOffset {
  x: number;
  y: number;
}

interface AnchorObject {
  fabricObject: CustomFabricObject;
  anchorEl: Element | null;
  overlayEl?: Element | null;
  anchorOffset: AnchorOffset;
}

export interface CustomFabricObject extends FabricObject {
  id?: string;
}

interface CanvasStore {
  canvas: Canvas | null;
  canvasRef: RefObject<HTMLCanvasElement> | null;
  objectMap: Map<string, AnchorObject>;

  setCanvas: (canvas: Canvas) => void;
  setCanvasRef: (canvasRef: RefObject<HTMLCanvasElement> | null) => void;

  addObject: (
    fabricObject: CustomFabricObject,
    anchorEl: Element | null,
    overlayEl?: Element | null,
  ) => void;
  updateAnchorById: (
    id: string,
    anchorEl: Element | null,
    overlayEl?: Element | null,
  ) => void;
  removeObjectById: (id: string) => void;
  clearCanvas: () => void;
}

const INIT_STATE = {
  canvas: null,
  canvasRef: null,
  objectMap: new Map<string, AnchorObject>(),
};

export const useCanvasState = create<CanvasStore>((set) => ({
  ...INIT_STATE,

  setCanvas: (canvas: Canvas) => set({ canvas }),
  setCanvasRef: (canvasRef: RefObject<HTMLCanvasElement> | null) =>
    set({ canvasRef }),

  addObject: (
    fabricObject: CustomFabricObject,
    anchorEl: Element | null,
    overlayEl?: Element | null,
  ) =>
    set((state) => {
      const id = uuidv4();
      fabricObject.id = id;
      state.canvas?.add(fabricObject);

      const anchorOffset = getOffset(fabricObject, anchorEl);
      appendOverlayEl(state.canvas, fabricObject, overlayEl);

      const newMap = new Map(state.objectMap);
      newMap.set(id, { fabricObject, anchorEl, overlayEl, anchorOffset });
      return { objectMap: newMap };
    }),

  updateAnchorById: (
    id: string,
    anchorEl: Element | null,
    overlayEl?: Element | null,
  ) =>
    set((state) => {
      const newMap = new Map(state.objectMap);
      if (newMap.has(id)) {
        const updatedObject = newMap.get(id);
        if (updatedObject) {
          updatedObject.anchorOffset = getOffset(
            updatedObject.fabricObject,
            anchorEl,
          );
          updatedObject.anchorEl = anchorEl;
          if (overlayEl) updatedObject.overlayEl = overlayEl;
          updateOverlayElPos(
            updatedObject.fabricObject,
            updatedObject.overlayEl,
          );
          newMap.set(id, updatedObject);
        }
      }
      return { objectMap: newMap };
    }),

  removeObjectById: (id: string) =>
    set((state) => {
      if (!id) return state;
      const newMap = new Map(state.objectMap);
      const objToRemove = newMap.get(id);
      if (objToRemove) {
        state.canvas?.remove(objToRemove.fabricObject);
        objToRemove.overlayEl?.remove();
      }
      newMap.delete(id);
      return { objectMap: newMap };
    }),

  clearCanvas: () =>
    set((state) => {
      const { canvas, objectMap } = state;
      if (!canvas) return state;

      objectMap.forEach((obj) => {
        obj.overlayEl?.remove();
      });

      canvas.clear();
      canvas.renderAll();
      return { objectMap: INIT_STATE.objectMap };
    }),
}));

const getOffset = (
  fabricObject: CustomFabricObject,
  anchorEl: Element | null,
) => {
  if (!anchorEl) {
    return { x: 0, y: 0 };
  }
  const anchorRect = anchorEl.getBoundingClientRect();
  const objectRect = fabricObject.getBoundingRect();
  return {
    x: anchorRect.left - objectRect.left,
    y: anchorRect.top - objectRect.top,
  };
};

const appendOverlayEl = (
  canvas: Canvas | null,
  fabricObject: CustomFabricObject,
  overlayEl?: Element | null,
) => {
  if (!canvas || !fabricObject || !overlayEl) return;
  const canvasContainer = canvas.getElement().parentElement;

  if (!canvasContainer) return;
  overlayEl.style.zIndex = -1;
  canvasContainer.appendChild(overlayEl);

  updateOverlayElPos(fabricObject, overlayEl);
};

export const updateOverlayElPos = (
  fabricObject: CustomFabricObject,
  overlayEl?: Element | null,
) => {
  if (!fabricObject || !overlayEl) return;
  const rectBounds = fabricObject.getBoundingRect();

  overlayEl.style.left = `${rectBounds.left}px`;
  overlayEl.style.top = `${rectBounds.top}px`;
  overlayEl.style.width = `${rectBounds.width - 2}px`;
  overlayEl.style.height = `${rectBounds.height - 2}px`;
};

export const updateAllObjectsPositions = () => {
  const { canvas, objectMap } = useCanvasState.getState();
  if (!canvas) return;

  objectMap.forEach(({ fabricObject, anchorEl, anchorOffset, overlayEl }) => {
    if (!anchorEl || !fabricObject) return;

    const anchorRect = anchorEl.getBoundingClientRect();
    fabricObject.set({
      left: anchorRect.left - anchorOffset.x,
      top: anchorRect.top - anchorOffset.y,
    });
    fabricObject.setCoords();
    updateOverlayElPos(fabricObject, overlayEl);
  });
  canvas.renderAll();
};

export const syncCanvasSize = () => {
  const { canvas } = useCanvasState.getState();
  if (!canvas) return;

  canvas.setDimensions({
    width: window.innerWidth,
    height: window.innerHeight,
  });

  updateAllObjectsPositions();
};

export const removeActiveObject = () => {
  const { canvas, removeObjectById } = useCanvasState.getState();
  if (!canvas) return;
  const activeObject = canvas.getActiveObject();
  if (!activeObject) return;
  const customActiveObject = activeObject as CustomFabricObject;
  if (!customActiveObject.id) return;
  removeObjectById(customActiveObject.id);
};
