import { useEffect, useState } from 'react';
import { getScreenResolutionPresets } from '../utils/screenResolution';
import { Resolution, ResolutionPreset } from '../types/resolution';

export const useScreenResolutionPresets = () => {
  const [resolutionPresets, setResolutionPresets] = useState<
    Record<ResolutionPreset, Resolution> | object
  >({});

  useEffect(() => {
    const getPresets = async () => {
      const resolutionPresets = await getScreenResolutionPresets();
      setResolutionPresets(resolutionPresets);
    };
    getPresets();
  }, []);

  return resolutionPresets;
};
