import Typography from '@mui/material/Typography';
import Switch from '@mui/material/Switch';
import FormControlLabel from '@mui/material/FormControlLabel';

interface SwitchSettingProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
  title: string;
  caption?: string;
  disabled?: boolean;
}

export const SwitchSetting = ({
  checked,
  onChange,
  title,
  caption = '',
  disabled = false,
}: SwitchSettingProps) => (
  <FormControlLabel
    disabled={disabled}
    labelPlacement="end"
    sx={{ userSelect: 'none' }}
    control={
      <Switch checked={checked} onChange={(_, value) => onChange(value)} />
    }
    label={
      <>
        <Typography variant="subtitle1">{title}</Typography>
        {caption && <Typography variant="body2">{caption}</Typography>}
      </>
    }
    componentsProps={{ typography: { width: '100%' } }}
  />
);
