import { useState } from 'react';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import { Section, SectionHeader } from './Section';
import { SwitchSetting } from '../SwitchSetting';

export default function PrivacySettings() {
  const [reportAnonymousUsage, setReportAnonymousUsage] = useState(false);

  return (
    <Section>
      <SectionHeader>Privacy</SectionHeader>
      <SwitchSetting
        checked={reportAnonymousUsage}
        title="Report anonymous usage statistics to Screencastify"
        onChange={(checked) => {
          setReportAnonymousUsage(checked);
          // eslint-disable-next-line no-console
          console.log(
            "'Report anonymous usage statistics to Screencastify' setting toggled to " +
              checked,
          );
        }}
      />
      <Button
        size="large"
        variant="outlined"
        color="info"
        onClick={() => {
          // eslint-disable-next-line no-console
          console.log("'Download user data' button clicked");
        }}
      >
        Download user data
      </Button>
      <Typography variant="body2">
        Questions? Contact us at privacy@screencastify.com.
      </Typography>
    </Section>
  );
}
