import { useEffect, useContext } from 'react';
import { CursorCanvasContext } from '../providers/CursorCanvasProvider';

export const useBlockNavigation = () => {
  const canvasRef = useContext(CursorCanvasContext);

  useEffect(() => {
    if (!canvasRef.current) return;
    canvasRef.current.style.pointerEvents = 'auto';
    canvasRef.current.style.userSelect = 'none';

    let wheelEventEndTimeout: NodeJS.Timeout;
    const handleScroll = () => {
      if (!canvasRef.current) return;
      canvasRef.current.style.pointerEvents = 'none';
      clearTimeout(wheelEventEndTimeout);
      wheelEventEndTimeout = setTimeout(() => {
        if (!canvasRef.current) return;
        canvasRef.current.style.pointerEvents = 'auto';
      }, 50);
    };
    document.addEventListener('wheel', handleScroll);

    return () => {
      if (!canvasRef.current) return;
      canvasRef.current.style.pointerEvents = 'none';
      canvasRef.current.style.userSelect = 'auto';
      document.removeEventListener('wheel', handleScroll);
    };
  }, []);

  return null;
};
