import { useRef } from 'react';
import { observer } from 'mobx-react-lite';
import { useEvent } from '../../../hooks/useEvent.hook';
import {
  useDrawingState,
  useEraserState,
} from '../../../state/context/useDrawingToolsState.hook';
import { CURSOR_LOGO } from './cursorLogo';
import { useBlockNavigation } from '../../../hooks/useBlockNavigation';
import { CURSOR_TYPE, useCustomCursor } from '../../../hooks/useCustomCursor';
import { usePointerResizeShortcuts } from '../../../hooks/usePointerResizeShortcuts';

export const EraserMode = observer(() => {
  const windowRef = useRef(window);
  const drawingState = useDrawingState();
  const eraserState = useEraserState();

  useBlockNavigation();
  useCustomCursor({
    type: CURSOR_TYPE.ERASER,
    cursor: CURSOR_LOGO.ERASER,
  });
  usePointerResizeShortcuts();

  useEvent(windowRef, 'pointerdown', (event) => {
    if (eraserState.isEraserActive) return;
    eraserState.startEraser(event.clientX, event.clientY, drawingState.size);
  });

  useEvent(windowRef, 'pointermove', (event) => {
    if (!eraserState.isEraserActive) return;
    eraserState.activeEraser?.moveTo(event.clientX, event.clientY);
  });

  useEvent(windowRef, 'pointercancel', () => {
    eraserState.cancelEraser();
  });

  useEvent(windowRef, 'pointerup', (event) => {
    if (!eraserState.isEraserActive) return;
    eraserState.activeEraser?.moveTo(event.clientX, event.clientY);
    drawingState.addElement(eraserState.activeEraser);
    eraserState.cancelEraser();
  });

  return null;
});
