import { ReactElement, ReactNode } from 'react';
import { observer } from 'mobx-react-lite';
import ClickAwayListener, {
  ClickAwayListenerProps,
} from '@mui/material/ClickAwayListener';
import Grow from '@mui/material/Grow';
import MenuItem, { MenuItemProps } from '@mui/material/MenuItem';
import MenuList from '@mui/material/MenuList';
import Paper from '@mui/material/Paper';
import Popper, { PopperProps } from '@mui/material/Popper';
import HomeRounded from '@mui/icons-material/HomeRounded';
import HelpIcon from '@mui/icons-material/HelpRounded';
import LogoutIcon from '@mui/icons-material/LogoutRounded';
import ContentCutRoundedIcon from '@mui/icons-material/ContentCutRounded';
import SettingsIcon from '@mui/icons-material/SettingsRounded';
import SwapIcon from '@mui/icons-material/SwapHorizRounded';
import Typography from '@mui/material/Typography';
import VideoLibraryIcon from '@mui/icons-material/VideoLibrary';
import { environment } from '@castify/record-mv3/environment';
import { colors, safeWindowOpen } from '@cfy/fe-common';
import { focusControllerTab } from '../../utils/focusControllerTab';
import { signInToExtension, signOutOfExtension } from '../../auth';
import { useAuthStore } from '../../../stores';
import Box from '@mui/material/Box';
import Tooltip from '@mui/material/Tooltip';
import { useHomePageEnabledFflag } from '../../hooks/useHomePageEnabledFflag';

interface ListItem {
  id: string;
  label: string;
  icon: ReactElement;
  onClick: MenuItemProps['onClick'];
  textElement?: ReactNode;
}

interface Props {
  open: PopperProps['open'];
  anchorEl: PopperProps['anchorEl'];
  onClickAway: ClickAwayListenerProps['onClickAway'];
  isLocalStorageRedirect: boolean;
}
export const OptionsMenu = observer(
  ({ anchorEl, open, onClickAway, isLocalStorageRedirect }: Props) => {
    const isHomePageEnabled = useHomePageEnabledFflag();
    const home = {
      id: 'home',
      label: 'Home',
      icon: <HomeRounded />,
      onClick: () => {
        if (isLocalStorageRedirect) focusControllerTab();
        else safeWindowOpen(environment.externalLinks.homePage);
      },
    };

    const myVideos = {
      id: 'my-videos',
      label: 'My Library',
      icon: <VideoLibraryIcon />,
      onClick: () => {
        if (isLocalStorageRedirect) focusControllerTab();
        else safeWindowOpen(environment.externalLinks.myVideosPage);
      },
    };

    const editor = {
      id: 'editor',
      label: 'Editor',
      icon: <ContentCutRoundedIcon />,
      onClick: () => safeWindowOpen(environment.editUrl),
      textElement: (
        <Typography variant="body1">
          <strong>Castify</strong>Edit - AI Editor
        </Typography>
      ),
    };

    const options = {
      id: 'options',
      label: 'Options',
      icon: <SettingsIcon />,
      onClick: async () => await chrome.tabs.create({ url: 'options.html' }),
    };

    const help = {
      id: 'help',
      label: 'Help',
      icon: <HelpIcon />,
      onClick: () => safeWindowOpen(environment.externalLinks.supportPage),
    };

    const switchAccount = {
      id: 'switch-account',
      label: 'Switch Account',
      icon: <SwapIcon />,
      onClick: async () => {
        await signOutOfExtension();
        signInToExtension(true);
      },
    };

    const signOut = {
      id: 'sign-out',
      label: 'Sign Out',
      icon: <LogoutIcon />,
      onClick: async () => {
        await signOutOfExtension();
        chrome.tabs.query(
          { url: environment.webAppUrl + '/*' },
          (result: chrome.tabs.Tab[]) =>
            result.forEach((tab) => chrome.tabs.reload(Number(tab.id))),
        );
        window.location.reload();
      },
    };

    const menuItems: ListItem[] = [
      ...(isHomePageEnabled ? [home] : []),
      myVideos,
      editor,
      options,
      help,
      switchAccount,
      signOut,
    ];

    return (
      <Popper
        sx={{ zIndex: 100 }}
        open={open}
        anchorEl={anchorEl}
        transition
        disablePortal
      >
        {({ TransitionProps }) => (
          <Grow {...TransitionProps}>
            <Paper
              sx={{
                width: '320px',
                borderRadius: '8px',
                paddingTop: '12px',
              }}
            >
              <ClickAwayListener onClickAway={onClickAway}>
                <MenuList
                  autoFocusItem
                  data-testid="options-menu"
                  sx={{
                    '.MuiMenuItem-root': {
                      display: 'flex',
                      flexDirection: 'row',
                      gap: '32px',
                    },
                  }}
                >
                  {menuItems.map(
                    ({ id, icon, label, onClick, textElement }: ListItem) => (
                      <MenuItem
                        key={id}
                        data-testid={`options-menu-${id}`}
                        onClick={onClick}
                      >
                        {icon}
                        {textElement ? (
                          textElement
                        ) : (
                          <Typography>{label}</Typography>
                        )}
                      </MenuItem>
                    ),
                  )}
                </MenuList>
              </ClickAwayListener>
              <Box
                borderTop="1px solid #0000001F"
                padding="16px"
                display="flex"
                flexDirection="column"
                gap="10px"
              >
                <Tooltip
                  title={`${useAuthStore.getState().email}`}
                  placement="top"
                  componentsProps={{ tooltip: { sx: { textAlign: 'center' } } }}
                >
                  <Typography
                    color={colors.info}
                    textOverflow="ellipsis"
                    noWrap
                  >
                    {useAuthStore.getState().email}
                  </Typography>
                </Tooltip>
                <Box
                  component="img"
                  src="assets/images/castify-tm-logo.svg"
                  alt="Castify logo"
                  height="25px"
                  width="60px"
                />
              </Box>
            </Paper>
          </Grow>
        )}
      </Popper>
    );
  },
);

export default OptionsMenu;
