import { useAuthStore } from '../../stores';
import { logger } from './authLogger';

interface RefreshTokenResponse {
  success: boolean;
  token?: string;
  error?: string;
}

export const refreshFirebaseToken = async (): Promise<string> => {
  return new Promise((resolve) => {
    logger.info('Refreshing Firebase Token');
    chrome.runtime.sendMessage(
      { type: 'refreshFirebaseToken' },
      (response: RefreshTokenResponse) => {
        if (chrome.runtime.lastError) {
          logger.error(
            'refreshFirebaseToken - Error sending message to background script',
          );
          resolve('');
          return;
        }
        if (!response || !response.success || !response.token) {
          logger.error(
            `refreshFirebaseToken - ${
              response?.error || 'Failed to refresh Firebase token'
            }`,
          );
          resolve('');
          return;
        }

        useAuthStore.getState().setFirebaseAccessToken(response.token);
        resolve(response.token);
      },
    );
  });
};
