import { observer } from 'mobx-react-lite';
import { useDrawingState } from '../../state/context/useDrawingToolsState.hook';
import Timer3Rounded from '@mui/icons-material/Timer3Rounded';
import Timer10Rounded from '@mui/icons-material/Timer10Rounded';
import { InfinityIcon } from '../icons/InfinityIcon';
import IconButton from '@mui/material/IconButton';
import Tooltip from '@mui/material/Tooltip';
import Box from '@mui/material/Box';
import { PopperProps } from '@mui/material';
import { useRef, useState } from 'react';
import {
  DrawingToolFadeTimePopper,
  FADE_TIMER_OPTIONS,
} from './DrawingToolFadeTimePopper';

const FADE_TIMER_ICONS = {
  [FADE_TIMER_OPTIONS.THREE_MS]: (
    <Timer3Rounded sx={{ transform: 'scale(0.75)', color: '#424242' }} />
  ),
  [FADE_TIMER_OPTIONS.TEN_MS]: (
    <Timer10Rounded sx={{ transform: 'scale(0.75)', color: '#424242' }} />
  ),
  [FADE_TIMER_OPTIONS.ZERO]: <InfinityIcon />,
};

export const FadeTimer = observer(() => {
  const drawingState = useDrawingState();
  const popperAnchorRef = useRef<HTMLButtonElement>(null);
  const [isPopperOpen, setIsPopperOpen] = useState(false);

  //Needed make tooltips work within the injected context without this they render outside the shadow dom
  const tooltipPopperProps: Partial<PopperProps> = {
    disablePortal: true,
  };

  const handlePopoverToggle = () => {
    setIsPopperOpen((prevOpen) => !prevOpen);
  };

  return (
    <>
      <Tooltip
        title={'Fade timer'}
        placement="top"
        PopperProps={tooltipPopperProps}
      >
        <IconButton
          ref={popperAnchorRef}
          onClick={handlePopoverToggle}
          sx={{
            width: '28px',
            height: '28px',
          }}
        >
          <Box display="flex" justifyContent="center" alignItems="center">
            {FADE_TIMER_ICONS[drawingState.fadeTimer]}
          </Box>
        </IconButton>
      </Tooltip>
      <DrawingToolFadeTimePopper
        isPopperOpen={isPopperOpen}
        setIsPopperOpen={setIsPopperOpen}
        popperRef={popperAnchorRef}
      />
    </>
  );
});
