import { useEffect } from 'react';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';

const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'useLoadFonts',
    buildId: currentVersion,
  },
);

export const useLoadFonts = () => {
  useEffect(() => {
    const loadFont = async (
      fontName: string,
      fontUrl: string,
      fontWeight = 'normal',
      fontStyle = 'normal',
    ) => {
      try {
        const res = await fetch(fontUrl);
        const fontData = await res.arrayBuffer();
        const font = new FontFace(fontName, fontData, {
          weight: fontWeight,
          style: fontStyle,
        });
        await font.load();
        document.fonts.add(font);
      } catch (e) {
        logger.error('Error on load fonts', e);
      }
    };

    loadFont(
      'Fellix',
      'https://cdn.castify.com/fonts/otf/Fellix-Bold.otf',
      '700',
    );

    loadFont(
      'Fellix',
      'https://cdn.castify.com/fonts/otf/Fellix-Regular.otf',
      '400',
    );
  }, []);

  return null;
};
