import { useRef, useState } from 'react';
import { useEvent } from '../../../hooks/useEvent.hook';
import { styled } from '../../../styled';
import { colors } from '@cfy/fe-common';
import { useDrawingState } from '../../../state/context/useDrawingToolsState.hook';
import { observer } from 'mobx-react-lite';

interface DrawingCircleProps extends React.CSSProperties {
  '--size'?: string;
  '--clientX'?: number;
  '--clientY'?: number;
}

const DrawingCircle = styled<DrawingCircleProps>('div', {
  '--size': '16px',
  '--clientX': 0,
  '--clientY': 0,

  background: 'transparent',
  pointerEvents: 'none',
  borderRadius: '50%',
  width: 'var(--size)',
  height: 'var(--size)',
  transform: 'translate(-50%, -50%)',
  position: 'fixed',
  left: 'calc(var(--clientX) * 1px)',
  top: 'calc(var(--clientY) * 1px)',
  boxSizing: 'border-box',
  border: `1.5px dashed ${colors.gray[400]}`,
});

export const DrawingPointer = observer(() => {
  const windowRef = useRef(window);
  const { size } = useDrawingState();

  const [x, setX] = useState<number | null>(null);
  const [y, setY] = useState<number | null>(null);

  useEvent(windowRef, 'pointermove', (event) => {
    setX(event.clientX);
    setY(event.clientY);
  });

  if (!x || !y) return null;

  return (
    <DrawingCircle
      data-testid="DrawingCircle"
      style={{
        '--clientX': x,
        '--clientY': y,
        '--size': `${size}px`,
      }}
    />
  );
});
