import { useMemo } from 'react';
import Slider from '@mui/material/Slider';
import styles from './ColorSlider.styles';

const hslToColorNumber = (hslColor: string): number => {
  const matches = hslColor.match(/(\d+)/);
  if (!matches) return 0;
  return Number(matches[0]);
};

interface ColorSliderProps {
  hslColor: string;
  onColorChange(hslColor: string): void;
}
export const ColorSlider = ({
  hslColor = 'hsl(0, 100%, 50%)',
  onColorChange = () => {},
}: ColorSliderProps) => {
  const colorNumber = useMemo(() => hslToColorNumber(hslColor), [hslColor]);

  const handleChange = (_: Event, newValue: number | number[]) => {
    onColorChange(`hsl(${newValue}, 100%, 50%)`);
  };

  return (
    <div css={styles.slider(colorNumber)}>
      <Slider
        aria-label="Pen Colors"
        value={colorNumber}
        min={0}
        max={338}
        onChange={handleChange}
      />
    </div>
  );
};
