import { observer } from 'mobx-react-lite';
import { useCursorModeState } from '../../../state/context/useDrawingToolsState.hook';
import { Clicks, Fireworks, Focus } from '../../cursorModes';
import { CursorModes } from '../../../consts/cursorModes';
import { ReactElement } from 'react';

const CURSOR_MODE: Record<CursorModes, ReactElement | null> = {
  classic: null,
  clicks: <Clicks />,
  focus: <Focus />,
  fireworks: <Fireworks />,
};

export const CursorMode = observer(() => {
  const cursorModeState = useCursorModeState();
  return CURSOR_MODE[cursorModeState.cursorMode];
});
