import Check from '@mui/icons-material/Check';
import Grow from '@mui/material/Grow';
import MenuItem from '@mui/material/MenuItem';
import MenuList from '@mui/material/MenuList';
import Paper from '@mui/material/Paper';
import Popper from '@mui/material/Popper';
import Typography from '@mui/material/Typography';
import ClickAwayListener from '@mui/material/ClickAwayListener';
import { observer } from 'mobx-react-lite';
import { useDrawingState } from '../../state/context/useDrawingToolsState.hook';
import styles from './DrawingToolFadeTimePopper.styles';

const FADE_TIMER_LABELS = {
  THREE: '3 seconds',
  TEN: '10 seconds',
  NEVER: 'Never',
};

export const FADE_TIMER_OPTIONS = {
  THREE_MS: 3000,
  TEN_MS: 10000,
  ZERO: 0,
};

const DEFAULT_TIMER = FADE_TIMER_OPTIONS.ZERO;

const FADE_TIMER_BY_LABEL = {
  [FADE_TIMER_LABELS.THREE]: FADE_TIMER_OPTIONS.THREE_MS,
  [FADE_TIMER_LABELS.TEN]: FADE_TIMER_OPTIONS.TEN_MS,
  [FADE_TIMER_LABELS.NEVER]: FADE_TIMER_OPTIONS.ZERO,
};

interface IDrawingToolFadeTimerPopperProps {
  isPopperOpen: boolean;
  setIsPopperOpen: (value: boolean) => void;
  popperRef: React.RefObject<HTMLButtonElement>;
}
export const DrawingToolFadeTimePopper = observer(
  (props: IDrawingToolFadeTimerPopperProps) => {
    //used to access specific propertys of a users drawings
    const drawingState = useDrawingState();
    /**
     * This function handles clicks outside of the popper to close it
     * @param event
     * @returns void
     */
    const handlePopoverClose = (event: Event) => {
      if (
        props.popperRef.current &&
        props.popperRef.current.contains(event.target as HTMLElement)
      ) {
        return;
      }

      props.setIsPopperOpen(false);
    };

    /**
     * When a user clicks one of the menu options from the options list in the popper
     * we update the index selected in state to help show a checkmark if the user reopens the popper
     * then we close the popper. Lastly we update the mst store with the users fade timer selection
     *
     * @param event
     * @param index
     */
    const handleMenuItemClick = (
      event: React.MouseEvent<HTMLElement, MouseEvent>,
    ) => {
      const label = event.target.innerText;
      props.setIsPopperOpen(false);
      drawingState.setFadeTimer(FADE_TIMER_BY_LABEL[label] ?? DEFAULT_TIMER);
    };
    return (
      <Popper
        sx={{
          zIndex: 1,
        }}
        open={props.isPopperOpen}
        anchorEl={props.popperRef.current}
        role={undefined}
        transition
        disablePortal
      >
        {({ TransitionProps, placement }) => (
          <Grow
            {...TransitionProps}
            style={{
              transformOrigin:
                placement === 'bottom' ? 'center top' : 'center bottom',
            }}
          >
            <Paper css={styles.penFadeTimerPopper}>
              <Typography css={styles.popperHeading}>Fade time</Typography>
              <ClickAwayListener onClickAway={handlePopoverClose}>
                <MenuList autoFocusItem>
                  {Object.values(FADE_TIMER_LABELS).map((option) => (
                    <MenuItem
                      css={styles.popperMenuItem}
                      key={option}
                      selected={
                        FADE_TIMER_BY_LABEL[option] === drawingState.fadeTimer
                      }
                      onClick={(event) => handleMenuItemClick(event)}
                    >
                      <div css={styles.popperMenuItemOption}>
                        {FADE_TIMER_BY_LABEL[option] ===
                          drawingState.fadeTimer && <Check />}
                      </div>
                      <div>{option}</div>
                    </MenuItem>
                  ))}
                </MenuList>
              </ClickAwayListener>
            </Paper>
          </Grow>
        )}
      </Popper>
    );
  },
);
