import { useEffect, useRef } from 'react';
import { TPointerEventInfo, Rect } from 'fabric';
import {
  CustomFabricObject,
  useCanvasState,
  getElementUnderFabricObject,
  useCanvasCursor,
  useFabricCanvas,
  removeActiveObject,
} from '../../../state/canvas';

const MIN_SIZE = 5;

const createBlurEl = () => {
  const overlayEl = document.createElement('div');
  overlayEl.style.position = 'absolute';
  overlayEl.style.backdropFilter = 'blur(8px) saturate(100%)';
  overlayEl.style.WebkitBackdropFilter = 'blur(8px) saturate(100%)';
  overlayEl.style.backgroundColor = 'transparent';
  overlayEl.style.border = '1px solid rgba(255, 255, 255, 0.125)';
  overlayEl.style.pointerEvents = 'none';
  return overlayEl;
};

export const BlurMode = () => {
  const [canvas, addObject, removeObjectById, updateAnchorById] =
    useCanvasState((s) => [
      s.canvas,
      s.addObject,
      s.removeObjectById,
      s.updateAnchorById,
    ]);

  const isDrawing = useRef(false);
  const startPointer = useRef<{ x: number; y: number } | null>(null);
  const tempRect = useRef<CustomFabricObject | null>(null);

  useFabricCanvas();
  useCanvasCursor({ default: 'crosshair', hover: 'pointer', move: 'move' });

  useEffect(() => {
    if (!canvas) return;

    const handleMouseDown = (
      event: TPointerEventInfo<MouseEvent | TouchEvent>,
    ) => {
      const target = canvas.findTarget(event.e);
      if (target) return;

      const pointer = canvas.getViewportPoint(event.e);
      startPointer.current = pointer;
      isDrawing.current = true;

      tempRect.current = new Rect({
        left: pointer.x,
        top: pointer.y,
        width: 1,
        height: 1,
        backgroundColor: 'transparent',
        fill: 'transparent',
        borderColor: '#FFC107',
        editingBorderColor: '#FFC107',
        borderDashArray: [5, 5],
        borderScaleFactor: 2,
        cornerColor: '#FFC107',
        cornerStyle: 'circle',
        cornerSize: 14,
        transparentCorners: false,
        borderOpacityWhenMoving: 1,
        lockRotation: true,
        hasRotatingPoint: false,
      });

      addObject(
        tempRect.current,
        getElementUnderFabricObject(tempRect.current),
        createBlurEl(),
      );
    };

    const handleMouseMove = (
      event: TPointerEventInfo<MouseEvent | TouchEvent>,
    ) => {
      if (!isDrawing.current || !tempRect.current || !startPointer.current)
        return;

      const pointer = canvas.getViewportPoint(event.e);
      const { x, y } = startPointer.current;

      const width = Math.abs(pointer.x - x);
      const height = Math.abs(pointer.y - y);

      tempRect.current.set({
        left: Math.min(x, pointer.x),
        top: Math.min(y, pointer.y),
        width,
        height,
      });

      tempRect.current.setCoords();

      if (!tempRect.current.id) return;
      updateAnchorById(
        tempRect.current.id,
        getElementUnderFabricObject(tempRect.current),
      );
      canvas.renderAll();
    };

    const handleMouseUp = () => {
      if (!isDrawing.current || !tempRect.current) return;

      const finalRect = tempRect.current as CustomFabricObject;
      if (!finalRect.id) return;

      finalRect.on('modified', () => {
        if (!finalRect.id) return;
        updateAnchorById(finalRect.id, getElementUnderFabricObject(finalRect));
      });

      finalRect.on('scaling', () => {
        if (!finalRect.id) return;
        updateAnchorById(finalRect.id, getElementUnderFabricObject(finalRect));
      });

      finalRect.on('moving', () => {
        if (!finalRect.id) return;
        updateAnchorById(finalRect.id, getElementUnderFabricObject(finalRect));
      });

      finalRect.on('rotating', () => {
        if (!finalRect.id) return;
        updateAnchorById(finalRect.id, getElementUnderFabricObject(finalRect));
      });

      updateAnchorById(finalRect.id, getElementUnderFabricObject(finalRect));

      if (finalRect.width < MIN_SIZE && finalRect.height < MIN_SIZE)
        removeObjectById(finalRect.id);

      isDrawing.current = false;
      tempRect.current = null;
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Delete' || event.key === 'Backspace') {
        removeActiveObject();
      }
    };

    canvas.on('mouse:down', handleMouseDown);
    canvas.on('mouse:move', handleMouseMove);
    canvas.on('mouse:up', handleMouseUp);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      canvas.off('mouse:down', handleMouseDown);
      canvas.off('mouse:move', handleMouseMove);
      canvas.off('mouse:up', handleMouseUp);
      window.removeEventListener('keydown', handleKeyDown);
      canvas.discardActiveObject();
      canvas.renderAll();
    };
  }, [canvas, addObject, removeObjectById, updateAnchorById]);

  return null;
};
