import React, { forwardRef } from 'react';

export const styled = <
  CssProperties extends React.CSSProperties = React.CSSProperties,
  AdditionalProps = Record<never, never>,
>(
  element: string,
  style: CssProperties | ((props: AdditionalProps) => CssProperties),
) => {
  return forwardRef(
    (
      props: React.HTMLAttributes<HTMLOrSVGElement> &
        AdditionalProps & {
          style?: CssProperties;
        },
      ref,
    ) => {
      const componentStyle = style instanceof Function ? style(props) : style;
      return React.createElement(element, {
        ...props,
        ref,
        style: {
          ...(componentStyle ?? {}),
          ...(props.style ?? {}),
        },
      });
    },
  );
};
