import { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { observer } from 'mobx-react-lite';
import { Section, SectionHeader } from './Section';
import Button from '@mui/material/Button';
import {
  ControllerCommandProtocol,
  useControllerState,
} from '@castify/record-mv3/record-components';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogActions from '@mui/material/DialogActions';
import { setExtensionIcon } from '@castify/record-mv3/chrome-actions';
import { isSensitiveRecordingState } from '../../controller/util/isSensitiveRecordingState';
import { SwitchSetting } from '../SwitchSetting';

function ResetSettings() {
  const { recorderStatus, recordingSettings, reset } = useControllerState();
  const [searchParams] = useSearchParams();
  const [isOpen, setIsOpen] = useState(false);

  const handleResetAllData = async () => {
    if (isSensitiveRecordingState(recorderStatus)) {
      await ControllerCommandProtocol.delete();
      setExtensionIcon('stopped');
    }
    await reset();
    setIsOpen(false);
    window.close();
  };

  return (
    <Section>
      <SectionHeader>Debug Options</SectionHeader>
      <SwitchSetting
        title="Debug mode"
        checked={recordingSettings.debugMode}
        onChange={recordingSettings.toggleDebugMode}
      />
      {(recordingSettings.debugMode || searchParams.get('debug') !== null) && (
        <Button
          size="large"
          variant="outlined"
          color="error"
          onClick={() => setIsOpen(true)}
        >
          Reset Extension
        </Button>
      )}
      <Dialog open={isOpen} onClose={() => setIsOpen(false)}>
        <DialogTitle>Are you sure?</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Resetting the Screencastify extension will restore all of the
            original settings. This will also remove any recordings that are
            only stored locally and not saved to Google Drive. You should only
            use this option if you are hoping to clear all customized options as
            part of troubleshooting recording with Screencastify.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button variant="outlined" onClick={() => setIsOpen(false)}>
            Cancel
          </Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleResetAllData}
          >
            Yes, Delete
          </Button>
        </DialogActions>
      </Dialog>
    </Section>
  );
}

export default observer(ResetSettings);
