import {
  StorageType,
  usePersonalSettingsQueryValueByKey,
  UserPersonalSettingKeys,
} from '@castify/record-mv3/common';
import { useControllerState } from '@castify/record-mv3/record-components';
import { observer } from 'mobx-react-lite';
import { SwitchSetting } from '../SwitchSetting';
import { Section, SectionHeader } from './Section';
import { isEdge } from '@cfy/fe-common';

function StorageSettings() {
  const {
    recordingSettings: { videoStorageLocation, setVideoStorageLocation },
  } = useControllerState();
  const { data: personalStorage } = usePersonalSettingsQueryValueByKey(
    UserPersonalSettingKeys.PersistentStorage,
  );
  const storageName =
    personalStorage === StorageType.CLOUD
      ? 'Screencastify Storage'
      : 'your Google Drive';
  return (
    <Section>
      <SectionHeader>Where should we save your videos?</SectionHeader>
      <SwitchSetting
        checked={videoStorageLocation === 'google-drive'}
        title={`${storageName.replace('your ', '')} (Recommended)`}
        caption="Videos will automatically be saved within Screencastify. Access your videos from any device."
        onChange={(checked) => {
          setVideoStorageLocation(checked ? 'google-drive' : 'local-storage');
        }}
      />
      <SwitchSetting
        checked={videoStorageLocation === 'local-storage'}
        title="On my Local Device"
        caption={`Videos will be saved on your local browser and available for viewing. Not recommended on ${
          !isEdge() ? 'ChromeOS' : 'Edge'
        } `}
        onChange={(checked) => {
          setVideoStorageLocation(checked ? 'local-storage' : 'google-drive');
        }}
      />
    </Section>
  );
}

export default observer(StorageSettings);
