import Dexie, { Table } from 'dexie';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';

const MAX_MESSAGE_LIMIT = 1000;

export interface MessageLogEntry {
  id?: number;
  timestamp: string;
  type: chrome.runtime.MessageSender;
  content: unknown;
}

export class MessagesLogDb extends Dexie {
  messages!: Table<MessageLogEntry>;

  constructor() {
    super('MessagesLogDB');
    this.version(1).stores({
      messages: '++id, timestamp, type, content',
    });
  }
}
const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'record-mv3-message-indexed-db',
    buildId: currentVersion,
  },
);

export const manageLogEntries = (logEntry: MessageLogEntry) => {
  messagesIndexedDb.messages.count().then((count) => {
    if (count >= MAX_MESSAGE_LIMIT) {
      // Delete the oldest entry (smallest id)
      messagesIndexedDb.messages
        .orderBy('id')
        .first()
        .then((firstEntry) => {
          if (firstEntry && firstEntry.id !== undefined) {
            // Ensure `id` is also not undefined
            messagesIndexedDb.messages
              .delete(firstEntry.id)
              .then(() => {
                addLogEntry(logEntry);
              })
              .catch((err) => {
                //Do nothing when delete fails
                logger.warn('Failed to delete the oldest message:', err);
              });
          } else {
            logger.warn(
              `No valid entries found to delete, but ${MAX_MESSAGE_LIMIT} entries limit reached.`,
            );
            addLogEntry(logEntry); // Optional, handle according to your needs
          }
        });
    } else {
      addLogEntry(logEntry);
    }
  });
};

export const addLogEntry = (logEntry: MessageLogEntry) => {
  messagesIndexedDb.messages
    .add(logEntry)
    .then(() => {
      logger.info('Message logged successfully in DB.');
    })
    .catch((err) => {
      logger.error('Failed to log message in DB:', err);
    });
};

export const messagesIndexedDb = new MessagesLogDb();
