import { environment } from '@castify/record-mv3/environment';
import { checkGoogleDriveScopeAccess } from './util/shouldRefreshGoogleAccessToken';

/**
 * @async
 * @desc Exchange the user's Google ID token for a JWT.
 * @returns A JWT that can be used as a bearer token for HTTP requests.
 */
type JwtResponse = { token: string };
export const exchangeScreencasitfyToken = async (
  firebaseIdToken: string,
): Promise<string> => {
  const url = `${environment.authServiceUrl}/tokens`;
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      provider: 'firebase',
      credentials: { token: firebaseIdToken },
    }),
  });

  const data: JwtResponse = await response.json();
  return data.token;
};

export const exchangeGoogleAccessToken = async (
  screencastifyToken: string,
): Promise<string> => {
  const url = `${environment.authServiceUrl}/google-token`;
  const response = await fetch(url, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${screencastifyToken}`,
    },
  });

  const { token }: JwtResponse = await response.json();

  // Check if the Google token has correct scope
  const shouldRefresh = await checkGoogleDriveScopeAccess(token);
  if (shouldRefresh) {
    chrome.tabs.create({ url: environment.externalLinks.forceConsentSignIn });
  }

  return token;
};
