import { PropsWithChildren } from 'react';
import { SignInRequired } from '@castify/record-mv3/common';
import { createBrowserLogger } from '@cfy/fe-monitoring';
import { useAuthStore } from '@castify/record-mv3/common/stores';

const logger = createBrowserLogger('AuthGuard');

export const AuthGuard = ({ children }: PropsWithChildren) => {
  const isAuth = useAuthStore((s) => s.isAuth);

  if (!isAuth) {
    logger.info('User is not authenticated. Prompting to sign in');
    return <SignInRequired />;
  }

  return <>{children}</>;
};
