import {
  ControllerCommandProtocol,
  useControllerState,
} from '@castify/record-mv3/record-components';
import { observer } from 'mobx-react-lite';
import styles from './RecordingControls.styles';
import PauseRoundedIcon from '@mui/icons-material/PauseRounded';
import StopRoundedIcon from '@mui/icons-material/StopRounded';
import PlayArrowRoundedIcon from '@mui/icons-material/PlayArrowRounded';
import RestartAltRoundedIcon from '@mui/icons-material/RestartAltRounded';
import DeleteRoundedIcon from '@mui/icons-material/DeleteRounded';
import { colors } from '@cfy/fe-common';
import { Control } from './Control';
import { useEffect, useState } from 'react';

export const RecordingControls = observer(() => {
  const { recorderStatus } = useControllerState();
  const isPaused = recorderStatus === 'paused';
  const isRecording = recorderStatus === 'recording';

  const [showDialog, setShowDialog] = useState(false);
  const [dialogMsg, setDialogMsg] = useState('');
  const [dialogAction, setDialogAction] = useState<() => void>(() => () => {});

  useEffect(() => {
    if (!showDialog || !dialogMsg) return;
    if (window.confirm(dialogMsg)) dialogAction();
    setShowDialog(false);
    setDialogMsg('');
    setDialogAction(() => () => {});
  }, [showDialog, dialogMsg]);

  const handleRestart = () => {
    setShowDialog(true);
    setDialogMsg(
      'Are you sure? Restarting will permanently delete the current recording and automatically start a new one.',
    );
    setDialogAction(() => () => ControllerCommandProtocol.restart(true));
  };

  const handleDelete = () => {
    setShowDialog(true);
    setDialogMsg(
      'Are you sure? Deleting this recording will remove all current video progress and cannot be undone.',
    );
    setDialogAction(() => () => ControllerCommandProtocol.delete());
  };

  return (
    <div
      css={[
        styles.videoControls,
        styles.recordingControls({
          isDisabled: !isRecording && !isPaused,
        }),
      ]}
    >
      <Control
        data-pendo-event="MV3-clk-stop"
        title="End recording"
        label="stop recording"
        onClick={() => ControllerCommandProtocol.stop()}
      >
        <StopRoundedIcon sx={{ color: '#E81218' }} />
      </Control>
      {isPaused ? (
        <Control
          data-pendo-event="MV3-clk-resume"
          title="Resume"
          label="resume recording"
          onClick={() => ControllerCommandProtocol.resume()}
        >
          <PlayArrowRoundedIcon sx={{ color: colors.success }} />
        </Control>
      ) : (
        <Control
          data-pendo-event="MV3-clk-pause"
          title="Pause"
          label="pause recording"
          onClick={() => ControllerCommandProtocol.pause()}
        >
          <PauseRoundedIcon sx={{ color: colors.textSecondary }} />
        </Control>
      )}
      <Control
        data-pendo-event="MV3-clk-restart"
        title="Restart"
        label="restart recording"
        onClick={handleRestart}
      >
        <RestartAltRoundedIcon sx={{ color: colors.textSecondary }} />
      </Control>
      <Control
        data-pendo-event="MV3-clk-delete"
        title="Delete"
        label="delete recording"
        onClick={handleDelete}
      >
        <DeleteRoundedIcon sx={{ color: colors.textSecondary }} />
      </Control>
    </div>
  );
});
