import { types } from 'mobx-state-tree';
import { CursorModes } from '../consts/cursorModes';

export const CursorModeState = types
  .model('ModeState', {
    cursorMode: types.optional(
      types.union(
        types.literal('clicks'),
        types.literal('focus'),
        types.literal('classic'),
        types.literal('fireworks'),
      ),
      'classic',
    ),
  })
  .actions((self) => {
    return {
      setCursorMode(cursorMode: CursorModes) {
        self.cursorMode = cursorMode;
      },
    };
  });
