import { useEffect, useState } from 'react';
import { environment } from '@castify/record-mv3/environment';
import { initializeApp } from 'firebase/app';
import { getRemoteConfig, getBoolean } from 'firebase/remote-config';
import { getFflagNoCache } from './getFflagNoCache';

export const getUseSafeVideoCodecFflag = async (): Promise<boolean> => {
  return await getFflagNoCache('useSafeVideoCodec');
};

export const getSyncUseSafeVideoCodecFflag = (): boolean => {
  const firebaseApp = initializeApp(environment.firebaseConfig);
  const remoteConfig = getRemoteConfig(firebaseApp);
  return getBoolean(remoteConfig, 'useSafeVideoCodec') || false;
};

export const useSafeVideoCodecFflag = () => {
  const [isEnabled, setIsEnabled] = useState(false);

  useEffect(() => {
    const fetchFlag = async () => {
      const flagValue = await getUseSafeVideoCodecFflag();
      setIsEnabled(flagValue);
    };

    fetchFlag();
  }, []);

  return isEnabled;
};
