import { createSyncStore } from './createSyncStore';
import { STORE_OPTIONS } from './utils';

interface TeleprompterStore {
  useTeleprompter: boolean;
  isAIVideoScriptEnabled: boolean;
  showTeleprompterModal: boolean;
  showTeleprompter: boolean;
  scriptContent: string;
  videoTopic: string;
  setUseTeleprompter: (useTeleprompter: boolean) => void;
  setAIVideoScriptEnabled: (isAIVideoScriptEnabled: boolean) => void;
  setShowTeleprompterModal: (showTeleprompterModal: boolean) => void;
  setShowTeleprompter: (showTeleprompter: boolean) => void;
  setScriptContent: (scriptContent: string) => void;
  setVideoTopic: (videoTopic: string) => void;
  resetTeleprompterStore: () => void;
}

const INIT_STATE = {
  useTeleprompter: false,
  isAIVideoScriptEnabled: false,
  showTeleprompterModal: false,
  showTeleprompter: false,
  scriptContent: '',
  videoTopic: '',
};

export const useTeleprompterStore = createSyncStore<TeleprompterStore>(
  'useTeleprompterStore',
  {
    ...INIT_STATE,

    setUseTeleprompter: (useTeleprompter: boolean) => {
      const { set } = useTeleprompterStore.getState();
      set({ useTeleprompter });
    },
    setAIVideoScriptEnabled: (isAIVideoScriptEnabled: boolean) => {
      const { set } = useTeleprompterStore.getState();
      set({ isAIVideoScriptEnabled });
    },
    setShowTeleprompterModal: (showTeleprompterModal: boolean) => {
      const { set } = useTeleprompterStore.getState();
      set({ showTeleprompterModal });
    },
    setShowTeleprompter: (showTeleprompter: boolean) => {
      const { set } = useTeleprompterStore.getState();
      set({ showTeleprompter });
    },
    setScriptContent: (scriptContent: string) => {
      const { set } = useTeleprompterStore.getState();
      set({ scriptContent });
    },
    setVideoTopic: (videoTopic: string) => {
      const { set } = useTeleprompterStore.getState();
      set({ videoTopic });
    },
    resetTeleprompterStore: () => {
      const { useTeleprompter, isAIVideoScriptEnabled, set } =
        useTeleprompterStore.getState();
      set({ ...INIT_STATE, useTeleprompter, isAIVideoScriptEnabled });
    },
  },
  STORE_OPTIONS,
);
