import { observer } from 'mobx-react-lite';
import { useStickersState } from '../../state/context/useDrawingToolsState.hook';
import Box from '@mui/material/Box';
import { ToolButton } from '../utility/ToolButton';
import { objectKeys } from '@castify/record-mv3/common';
import EmojiEmotionsRoundedIcon from '@mui/icons-material/EmojiEmotionsRounded';
import { Emoji, STICKERS } from '../cursorModes/sticker/Sticker';
import { SHORTCUTS } from '../../consts/shortcuts';
import { colors } from '@cfy/fe-common';
import { Stickers } from '../../consts/stickers';

const STICKER_LABEL: Record<Stickers, string> = {
  smile: 'Smile',
  sunglasses: 'Sunglasses',
  'heart-eyes': 'Heart Eyes',
  h100: '100',
  'thumbs-up': 'Thumbs Up',
  party: 'Party',
};

interface StickersToolsProps {
  isActive?: boolean;
  isExpanded?: boolean;
  onSelect?: () => void;
}

export const StickersTools = observer(
  ({ isActive, isExpanded, onSelect = () => {} }: StickersToolsProps) => {
    if (!isActive && !isExpanded) return null;

    const { sticker, setSticker } = useStickersState();

    const stickersButtonProps = objectKeys(STICKERS).map((stickerName) => ({
      onClick: () => setSticker(stickerName),
      isSelected: sticker === stickerName,
      icon: STICKERS[stickerName],
      label: STICKER_LABEL[stickerName],
      pendo: `MV3-clk-emoji-${stickerName}`,
    }));

    return isActive && isExpanded ? (
      <Box
        height="32px"
        display="flex"
        justifyContent="center"
        alignItems="center"
        gap="4px"
        border="1px solid #0000001F"
        borderRadius="16px"
        padding="0 1px"
        boxSizing="border-box"
        sx={{ background: colors.gray['200'] }}
      >
        <ToolButton
          label={`Stickers (${SHORTCUTS['stickers-tool'].label})`}
          disabled
        >
          <EmojiEmotionsRoundedIcon sx={{ color: colors.gray['800'] }} />
        </ToolButton>
        {stickersButtonProps.map(
          ({ isSelected, onClick, icon, label, pendo }, i) => (
            <ToolButton
              data-pendo-event={pendo}
              key={`${label}-${i}`}
              label={label}
              isSelected={isSelected}
              onClick={onClick}
            >
              <Emoji>{icon}</Emoji>
            </ToolButton>
          ),
        )}
      </Box>
    ) : (
      <ToolButton
        data-pendo-event="MV3-clk-emoji-mode"
        label={`Stickers (${SHORTCUTS['stickers-tool'].label})`}
        onClick={onSelect}
        isSelected={isActive}
        isDefault
      >
        {isExpanded ? (
          <EmojiEmotionsRoundedIcon sx={{ color: colors.gray['800'] }} />
        ) : (
          <Emoji>{STICKERS[sticker]}</Emoji>
        )}
      </ToolButton>
    );
  },
);
