const EDGE_EXTENSION_STAGING_ID = 'nmiiicfgknbggkjakjfodhghbngmjmci';
const EDGE_EXTENSION_PROD_ID = 'pdgepnkbokhdgjnhfmklkijfbdgngccm';
// const PROD_EXTENSION_ID = 'mmeijimgabbpbgpdklnllpncmdofkcpn';
// const STAGING_EXTENSION_ID = 'hodjlilmbhaajegmnpfcpoehlbnlfcne';

export const getExtensionBrowserType = () => {
  if (
    chrome.runtime.id === EDGE_EXTENSION_STAGING_ID ||
    chrome.runtime.id === EDGE_EXTENSION_PROD_ID
  ) {
    return 'edge';
  } else {
    return 'chrome';
  }
};
