// Helper function to get a random number within a range
function random(min: number, max: number) {
  return Math.random() * (max - min) + min;
}

/** Individual colored trail in a Firework instance */
class Particle {
  // position on canvas.
  x: number;
  y: number;

  angle: number;
  speed: number;
  // friction will slow the particle down
  friction = 0.95;
  // gravity will be applied and pull the particle down
  gravity = 1;
  brightness: number;
  alpha = 1;
  hue: number;
  decay: number;
  coordinateCount = 15;
  coordinates: Array<[number, number]> = [];
  constructor(x: number, y: number, hue: number) {
    this.x = x;
    this.y = y;
    while (this.coordinateCount--) {
      this.coordinates.push([this.x, this.y]);
    }
    // set a random angle in all possible directions, in radians
    this.angle = random(0, Math.PI * 2);
    this.speed = random(1, 10);
    this.hue = random(hue - 50, hue + 50);
    this.brightness = random(50, 80);
    this.decay = random(0.015, 0.03);
  }

  /** Adjusts position and appearance for each tick of the animation loop */
  update(): boolean {
    this.coordinates.pop();
    this.coordinates.unshift([this.x, this.y]);
    // slow down the particle
    this.speed *= this.friction;
    // apply velocity
    this.x += Math.cos(this.angle) * this.speed;
    this.y += Math.sin(this.angle) * this.speed + this.gravity;
    // fade out the particle
    this.alpha -= this.decay;

    // remove the particle once the alpha is low enough, based on the passed in index
    if (this.alpha <= this.decay) {
      return false;
    }
    return true;
  }

  /** Commits updates to canvas */
  draw(ctx: CanvasRenderingContext2D) {
    ctx.beginPath();
    // move to the last tracked coordinates in the set, then draw a line to the current x and y
    ctx.moveTo(
      this.coordinates[this.coordinates.length - 1][0],
      this.coordinates[this.coordinates.length - 1][1],
    );
    ctx.lineTo(this.x, this.y);
    ctx.strokeStyle =
      'hsla(' +
      this.hue +
      ', 100%, ' +
      this.brightness +
      '%, ' +
      this.alpha +
      ')';
    ctx.stroke();
  }
}

/** Single Firework starburst that contains an array of particles */
export class Firework {
  // center point of firework
  tx: number;
  ty: number;

  particles: Particle[] = [];
  hue: number;
  brightness: number;

  constructor(x: number, y: number) {
    this.tx = x;
    this.ty = y;
    this.brightness = random(50, 70);
    this.hue = random(0, 360);

    let particleCount = 50;
    while (particleCount--) {
      this.particles.push(new Particle(this.tx, this.ty, this.hue));
    }
  }

  /** Controls animation loop for particles */
  play(ctx: CanvasRenderingContext2D) {
    if (this.particles.length) {
      window.requestAnimationFrame(() => this.play(ctx));
    }

    ctx.globalCompositeOperation = 'destination-out';
    // decrease the alpha property (fourth value in rgba) to create more prominent trails
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.fillRect(0, 0, window.innerWidth, window.innerHeight);
    ctx.globalCompositeOperation = 'lighter';

    // loop over each particle, draw it, update it
    let i = this.particles.length;
    while (i--) {
      this.particles[i].draw(ctx);
      if (!this.particles[i].update()) {
        this.particles.splice(i, 1);
      }
    }
  }
}
