import { theme } from '@cfy/fe-common';
import {
  componentErrorHandler,
  ErrorFallback,
  OnUnhandledRejection,
} from '@castify/record-mv3/error-handling';
import { ThemeProvider } from '@emotion/react';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { ErrorBoundary } from 'react-error-boundary';
import { Options } from './Options';
import { ControllerMstProvider } from '@castify/record-mv3/record-components';
import { BrowserRouter } from 'react-router-dom';
import { environment } from '@castify/record-mv3/environment';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { tracing, RemoteLoggerService } from '@cfy/fe-monitoring';
import { AuthGuard } from '../initializer/AuthGuard';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { SyncStoreProvider } from '@castify/record-mv3/common/stores';
import { PendoEventBridge } from '../pendo/PendoEventBridge';

const queryClient = new QueryClient();

if (environment.isObservabilityEnabled) {
  const attributes = {
    appName: 'mv3-options',
    buildId: chrome.runtime.getManifest().version,
  };
  new RemoteLoggerService(
    environment.logServiceUrl,
    getFirebaseAccessToken,
    attributes,
  );
  tracing({
    appName: 'mv3-options',
    version: chrome.runtime.getManifest().version,
    traceCollectorUrl: environment.otelCollectorUrl,
  });
}

const rootEl = document.getElementById('root');
if (!rootEl) {
  throw new Error('<div id="root" /> not found – cannot mount');
}

const root = createRoot(rootEl);
root.render(
  <StrictMode>
    <BrowserRouter>
      <ControllerMstProvider>
        <ErrorBoundary
          FallbackComponent={ErrorFallback}
          onError={componentErrorHandler}
        >
          <OnUnhandledRejection>
            <QueryClientProvider client={queryClient}>
              <ThemeProvider theme={theme}>
                <SyncStoreProvider>
                  <AuthGuard>
                    <PendoEventBridge>
                      <Options />
                    </PendoEventBridge>
                  </AuthGuard>
                </SyncStoreProvider>
              </ThemeProvider>
            </QueryClientProvider>
          </OnUnhandledRejection>
        </ErrorBoundary>
      </ControllerMstProvider>
    </BrowserRouter>
  </StrictMode>,
);
