import { ReactNode, RefObject, createContext } from 'react';
import { useFullScreenCanvas } from '../hooks/useFullScreenCanvas';

export const CursorCanvasContext = createContext<RefObject<HTMLCanvasElement>>({
  current: null,
});

export const CursorCanvasProvider = ({
  children,
}: {
  children: Array<ReactNode> | ReactNode;
}) => {
  const canvasRef = useFullScreenCanvas();
  return (
    <CursorCanvasContext.Provider value={canvasRef}>
      <canvas
        data-testid="CursorCanvas"
        ref={canvasRef}
        style={{
          pointerEvents: 'none',
          touchAction: 'none',
          userSelect: 'none',
        }}
      />
      {children}
    </CursorCanvasContext.Provider>
  );
};
