import { observer } from 'mobx-react-lite';
import MenuItem from '@mui/material/MenuItem';
import Stack from '@mui/material/Stack';
import Select from '@mui/material/Select';
import Typography from '@mui/material/Typography';
import {
  RESOLUTION_PRESETS,
  ResolutionPreset,
} from '@castify/record-mv3/common';

interface Props {
  selectedResolution: ResolutionPreset | 'OFF';
  setSelectedResolution(value: ResolutionPreset | 'OFF'): void;
  recordMaxResolutionEnabled: boolean;
}

export const LimitResolutionSelect = observer(
  ({
    selectedResolution,
    setSelectedResolution,
    recordMaxResolutionEnabled,
  }: Props) => {
    const resolutionPresets = {
      ...(RESOLUTION_PRESETS as Partial<typeof RESOLUTION_PRESETS>),
    };
    if (!recordMaxResolutionEnabled) {
      delete resolutionPresets['4k'];
    }

    return (
      <Select
        fullWidth
        size="small"
        value={selectedResolution}
        onChange={(event) => {
          setSelectedResolution(event.target.value as ResolutionPreset | 'OFF');
        }}
        renderValue={(value) => {
          if (value === 'OFF') {
            return value;
          } else {
            const { width, height } = RESOLUTION_PRESETS[value];
            return `${width}x${height}px`;
          }
        }}
      >
        <MenuItem key="OFF" value="OFF">
          <Typography>OFF</Typography>
        </MenuItem>
        {Object.entries(resolutionPresets).map(([key, value]) => (
          <MenuItem key={key} value={key}>
            <Stack direction="row" gap="8px">
              <Typography>{key}</Typography>
              <Typography variant="body2">
                {`(${value.width}x${value.height})`}
              </Typography>
            </Stack>
          </MenuItem>
        ))}
      </Select>
    );
  },
);
