import { types } from 'mobx-state-tree';
import { PenPathDrawing } from './drawing-elements/PenPathDrawing.mst';

export const PenState = types
  .model('PenState', {
    activePen: types.maybeNull(PenPathDrawing),
  })
  .views((self) => {
    return {
      get isPenActive(): boolean {
        return !!self.activePen;
      },
    };
  })
  .actions((self) => {
    return {
      startPen(x: number, y: number, color: string, size: number) {
        self.activePen = PenPathDrawing.create({
          color,
          size,
        });
        self.activePen.moveTo(x, y);
      },
      movePenTo(x: number, y: number) {
        if (!self.activePen) return;
        self.activePen.moveTo(x, y);
      },
      cancelPen() {
        if (!self.activePen) return;
        self.activePen = null;
      },
    };
  });
