import { environment } from '@castify/record-mv3/environment';
import { getAuth, signOut } from 'firebase/auth/web-extension';
import { initializeApp } from 'firebase/app';
import { logger } from './authLogger';

export const signOutOfExtension = async () => {
  logger.info('User -> Sign out');
  const firebaseApp = initializeApp(environment.firebaseConfig);
  const firebaseAuth = getAuth(firebaseApp);
  await signOut(firebaseAuth);
};
