import Box from '@mui/material/Box';
import Switch from '@mui/material/Switch';
import Tooltip from '@mui/material/Tooltip';
import { observer } from 'mobx-react-lite';
import { useEffect } from 'react';
import { useControllerState } from '../../state/ControllerStateProvider';
import { useDeviceList } from '../../state/useDeviceList.hook';
import styles from './Switch.styles';

export const UseVideoSwitch = observer(() => {
  const { recordingSettings } = useControllerState();
  const { cameraDetected, pendingRequest } = useDeviceList();

  const noCameraAvailable = !cameraDetected && !pendingRequest;

  useEffect(() => {
    if (noCameraAvailable && recordingSettings.useVideoDevice) {
      recordingSettings.setUseVideoDevice(false);
    }
  }, [cameraDetected, pendingRequest, recordingSettings, noCameraAvailable]);

  return (
    <Tooltip
      title={
        recordingSettings.useVideoDevice ? 'Turn off Camera' : 'Turn on Camera'
      }
      placement="top"
    >
      {/* Box needed to catch Tooltip pointer events when Button is disabled. */}
      <Box>
        <Switch
          aria-label="camera toggle"
          disabled={noCameraAvailable}
          checked={recordingSettings.useVideoDevice}
          onChange={(event) =>
            recordingSettings.setUseVideoDevice(event.target.checked)
          }
          css={styles('video', { isEnabled: recordingSettings.useVideoDevice })}
        />
      </Box>
    </Tooltip>
  );
});
