import { observer } from 'mobx-react-lite';
import { CURSOR_TYPE, useCustomCursor } from '../../../hooks/useCustomCursor';
import { useEvent } from '../../../hooks/useEvent.hook';
import {
  useDrawingState,
  useStickersState,
} from '../../../state/context/useDrawingToolsState.hook';
import { StickerDrawing } from '../../../state/drawing-elements/StickerDrawing.mst';
import { useBlockNavigation } from '../../../hooks/useBlockNavigation';
import { useStickersResizeShortcuts } from '../../../hooks/useStickersResizeShortcuts';

export const StickersMode = observer(() => {
  const windowRef = { current: window };
  const { sticker, size } = useStickersState();
  const drawingState = useDrawingState();

  useBlockNavigation();
  useCustomCursor({ type: CURSOR_TYPE.NONE, cursor: 'none' });
  useStickersResizeShortcuts();

  useEvent(windowRef, 'pointerdown', (event) => {
    const stickerDrawing = StickerDrawing.create({
      position: { x: event.clientX, y: event.clientY },
      sticker,
      size,
    });
    stickerDrawing.calculateAnchor(event.clientX, event.clientY);

    drawingState.addElement(stickerDrawing);
  });

  return null;
});
