import { useEffect } from 'react';
import { useUpdatingRef } from './useUpdatingRef.hook';

interface UseEventOptions {
  when?: boolean;
  passive?: boolean;
  preventDefault?: boolean;
  capture?: boolean;
}

export function useEvent<EventName extends keyof WindowEventMap>(
  targetRef: { current: Window | HTMLElement | null },
  eventName: EventName,
  handler: (event: WindowEventMap[EventName]) => unknown,
  options: Partial<UseEventOptions> = {},
) {
  const callbackRef = useUpdatingRef<typeof handler>(handler);
  const shouldExecRef = useUpdatingRef<boolean>(options.when ?? true);
  const preventDefaultRef = useUpdatingRef<boolean>(
    options.preventDefault ?? false,
  );
  useEffect(() => {
    const currentTarget = targetRef.current;
    if (!currentTarget) return;

    const execEvent: EventListener = (event) => {
      if (shouldExecRef.current) {
        if (preventDefaultRef.current) {
          event.preventDefault();
        }

        callbackRef.current(event as WindowEventMap[EventName]);
      }
    };

    currentTarget.addEventListener(eventName, execEvent, {
      passive: options.passive ?? false,
      capture: options.capture ?? false,
    });

    return () => {
      currentTarget.removeEventListener(eventName, execEvent);
    };

    // eslint thinks the generic EventType should be included in the deps list.
    //   eslint is wrong
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [callbackRef, shouldExecRef, options.passive]);
}
