import { useState } from 'react';
import { observer } from 'mobx-react-lite';
import { Section, SectionHeader } from './Section';
import { SwitchSetting } from '../SwitchSetting';
import { SelectSetting, Item } from '../SelectSetting';
import {
  BitratePreset,
  Codec,
  CODEC_H264,
  CODEC_VP8,
  CODEC_VP9,
  useSafeVideoCodecFflag,
} from '@castify/record-mv3/common';
import { useControllerState } from '@castify/record-mv3/record-components';
import { useSettingsStore } from '@castify/record-mv3/common/stores';

const QUALITY_OPTIONS: Item[] = [
  { value: 'high', label: 'highest quality (creates largest files)' },
  { value: 'medium', label: 'medium quality' },
  { value: 'low', label: 'lowest quality (creates smallest files)' },
];

interface CodecItem {
  label: string;
  value: Codec;
}

const CODEC_OPTIONS: CodecItem[] = [
  { value: CODEC_VP8, label: 'VP8' },
  { value: CODEC_VP9, label: 'VP9' },
  { value: CODEC_H264, label: 'H.264' },
];

export const AdvancedSettings = observer(() => {
  const { recordingSettings } = useControllerState();
  const defaultVideoCodec = useSettingsStore((s) => s.defaultVideoCodec);
  const setDefaultVideoCodec = useSettingsStore((s) => s.setDefaultVideoCodec);
  const [enableSingleAppRecording, setEnableSingleAppRecording] =
    useState(false);
  const isSafeVideoCodecEnabled = useSafeVideoCodecFflag();

  const selectedCodecOption =
    CODEC_OPTIONS.find((option) => option.value === defaultVideoCodec) ||
    CODEC_OPTIONS[0];
  return (
    <Section>
      <SectionHeader>Advanced</SectionHeader>
      <SelectSetting
        title="Quality vs. file size"
        caption={`Record with ${recordingSettings.bitrate} quality.`}
        items={QUALITY_OPTIONS}
        selectedItem={recordingSettings.bitrate}
        onChange={(value) => {
          recordingSettings.setBitrate(value as BitratePreset);
        }}
      />
      {!isSafeVideoCodecEnabled && (
        <SelectSetting
          title="Video Codec"
          caption={`Record with ${selectedCodecOption.label} codec.`}
          items={CODEC_OPTIONS}
          selectedItem={defaultVideoCodec}
          onChange={(value) => {
            setDefaultVideoCodec(value as Codec);
          }}
        />
      )}
      <SwitchSetting
        checked={recordingSettings.useNoiseSuppression}
        title="Optimize mic audio for voice"
        caption="Disable if you want to record background noise or use professional audio equipment."
        onChange={(checked) => {
          recordingSettings.setUseNoiseSuppression(checked);
        }}
      />
      <SwitchSetting
        checked={enableSingleAppRecording}
        title="Enable single application recording"
        caption="Gives you the option of recording only a single application after starting a desktop recording. Will not capture some dropdown menus or that application in full-screen mode."
        onChange={(checked) => {
          setEnableSingleAppRecording(checked);
        }}
      />
    </Section>
  );
});
