import { types } from 'mobx-state-tree';
import { RectangleDrawing } from './drawing-elements/RectangleDrawing.mst';

export const RectangleState = types
  .model('RectangleState', {
    activeRectangle: types.maybeNull(RectangleDrawing),
  })
  .views((self) => {
    return {
      get isRectangleActive(): boolean {
        return !!self.activeRectangle;
      },
    };
  })
  .actions((self) => {
    return {
      startRectangle(x: number, y: number, color: string, size: number) {
        self.activeRectangle = RectangleDrawing.create({
          origin: { x, y },
          terminus: { x, y },
          color,
          size,
        });
      },
      updateRectangle(x: number, y: number) {
        if (!self.activeRectangle) return;
        self.activeRectangle.updateTerminus(x, y);
      },
      cancelRectangle() {
        if (!self.activeRectangle) return;
        self.activeRectangle = null;
      },
    };
  });
