import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { useEffect } from 'react';
import { syncCanvasSize, updateAllObjectsPositions } from './useCanvasState';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';

const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'useSyncCanvas',
    buildId: currentVersion,
  },
);

export const useSyncCanvas = () => {
  // Sync canvas in iframe context
  useIframeScrollSync(updateAllObjectsPositions);

  useEffect(() => {
    window.addEventListener('scroll', updateAllObjectsPositions);
    window.addEventListener('wheel', updateAllObjectsPositions);
    window.addEventListener('resize', syncCanvasSize);

    return () => {
      window.removeEventListener('scroll', updateAllObjectsPositions);
      window.removeEventListener('wheel', updateAllObjectsPositions);
      window.removeEventListener('resize', syncCanvasSize);
    };
  }, []);
};

export const useIframeScrollSync = (callback: () => void) => {
  useEffect(() => {
    const attachIframeListeners = () => {
      const iframes = document.querySelectorAll('iframe');
      iframes.forEach((iframe) => {
        try {
          const iframeDocument = (iframe as HTMLIFrameElement).contentDocument;
          if (iframeDocument) {
            iframeDocument.addEventListener('scroll', callback);
            iframeDocument.addEventListener('wheel', callback);
          }
        } catch (err) {
          logger.warn('attachIframeListeners - Error on iframe content:', err);
        }
      });
    };

    const detachIframeListeners = () => {
      const iframes = document.querySelectorAll('iframe');
      iframes.forEach((iframe) => {
        try {
          const iframeDocument = (iframe as HTMLIFrameElement).contentDocument;
          if (iframeDocument) {
            iframeDocument.removeEventListener('scroll', callback);
            iframeDocument.removeEventListener('wheel', callback);
          }
        } catch (err) {
          logger.warn('detachIframeListeners - Error on iframe content:', err);
        }
      });
    };

    // Observe and subscribe to dynamic iframes
    const observer = new MutationObserver(() => attachIframeListeners());
    observer.observe(document.body, { childList: true, subtree: true });

    attachIframeListeners();

    return () => {
      detachIframeListeners();
      observer.disconnect();
    };
  }, [callback]);
};
