import { ReactElement } from 'react';
import { observer } from 'mobx-react-lite';
import { useCursorModeState } from '../../state/context/useDrawingToolsState.hook';
import Box from '@mui/material/Box';
import { Cursor } from '../icons/Cursor';
import { Spotlight } from '../icons/Spotlight';
import { Fireworks } from '../icons/Fireworks';
import { Highlight } from '../icons/Highlight';
import { CursorModes } from '../../consts/cursorModes';
import { ToolButton } from '../utility/ToolButton';
import { SHORTCUTS } from '../../consts/shortcuts';

const CURSOR_ICON: Record<CursorModes, ReactElement> = {
  classic: <Cursor />,
  clicks: <Highlight />,
  focus: <Spotlight />,
  fireworks: <Fireworks />,
};

interface CursorToolsProps {
  isActive?: boolean;
  isExpanded?: boolean;
  onSelect?: () => void;
}

export const CursorTools = observer(
  ({ isActive, isExpanded, onSelect = () => {} }: CursorToolsProps) => {
    if (!isActive && !isExpanded) return null;

    const cursorModeState = useCursorModeState();

    const cursorModeButtonProps = [
      {
        onClick: () => cursorModeState.setCursorMode('classic'),
        isSelected: cursorModeState.cursorMode === 'classic',
        icon: <Cursor />,
        label: `Cursor (${SHORTCUTS['classic-cursor'].label})`,
        pendo: 'MV3-clk-cursor',
      },
      {
        onClick: () => cursorModeState.setCursorMode('clicks'),
        isSelected: cursorModeState.cursorMode === 'clicks',
        icon: <Highlight />,
        label: `Highlight (${SHORTCUTS['clicks-cursor'].label})`,
        pendo: 'MV3-clk-highlight',
      },
      {
        onClick: () => cursorModeState.setCursorMode('focus'),
        isSelected: cursorModeState.cursorMode === 'focus',
        icon: <Spotlight />,
        label: `Spotlight (${SHORTCUTS['focus-cursor'].label})`,
        pendo: 'MV3-clk-spotlight',
      },
      {
        onClick: () => cursorModeState.setCursorMode('fireworks'),
        isSelected: cursorModeState.cursorMode === 'fireworks',
        icon: <Fireworks />,
        label: `Fireworks (${SHORTCUTS['fireworks-cursor'].label})`,
        pendo: 'MV3-clk-fireworks',
      },
    ];

    return isActive && isExpanded ? (
      <Box
        height="32px"
        display="flex"
        justifyContent="center"
        alignItems="center"
        gap="4px"
        border="1px solid #0000001F"
        borderRadius="16px"
        padding="0 1px"
        boxSizing="border-box"
        sx={{ background: '#EEEEEE' }}
      >
        {cursorModeButtonProps.map(
          ({ isSelected, onClick, icon, label, pendo }, i) => (
            <ToolButton
              data-pendo-event={pendo}
              key={`${label}-${i}`}
              label={label}
              isSelected={isSelected}
              onClick={onClick}
            >
              {icon}
            </ToolButton>
          ),
        )}
      </Box>
    ) : (
      <ToolButton
        data-pendo-event="MV3-clk-cursor-mode"
        label={`Cursor Mode (${SHORTCUTS['classic-cursor'].label})`}
        onClick={onSelect}
        isSelected={isActive}
        isDefault
      >
        {CURSOR_ICON[cursorModeState.cursorMode]}
      </ToolButton>
    );
  },
);
