import { types } from 'mobx-state-tree';
import { EraserPathDrawing } from './drawing-elements/EraserPathDrawing.mst';

export const EraserState = types
  .model('EraserState', {
    activeEraser: types.maybeNull(EraserPathDrawing),
  })
  .views((self) => {
    return {
      get isEraserActive(): boolean {
        return !!self.activeEraser;
      },
    };
  })
  .actions((self) => {
    return {
      startEraser(x: number, y: number, size: number) {
        self.activeEraser = EraserPathDrawing.create({
          size,
          points: [{ x, y }],
        });
        self.activeEraser.moveTo(x, y);
      },
      moveEraserTo(x: number, y: number) {
        if (!self.activeEraser) return;
        self.activeEraser.moveTo(x, y);
      },
      cancelEraser() {
        if (!self.activeEraser) return;
        self.activeEraser = null;
      },
    };
  });
