import { useState } from 'react';
import Link from '@mui/material/Link';
import { Section, SectionHeader } from './Section';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import {
  ClearAllIcon,
  Cursor,
  EraserIcon,
  Fireworks,
  PenIcon,
  RectangleIcon,
  Spotlight,
  Highlight,
  SHORTCUTS,
} from '@castify/record-mv3/drawing-tools';
import EmojiEmotionsRoundedIcon from '@mui/icons-material/EmojiEmotionsRounded';
import VideocamRoundedIcon from '@mui/icons-material/VideocamRounded';
import ExpandRoundedIcon from '@mui/icons-material/ExpandRounded';
import VisibilityOffRoundedIcon from '@mui/icons-material/VisibilityOffRounded';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import Box from '@mui/material/Box';
import { colors } from '@cfy/fe-common';

const DRAWING_SHORTCUTS = [
  {
    icon: <VisibilityOffRoundedIcon />,
    name: 'Show/hide toolbar',
    shortcut: SHORTCUTS['toolbar-show-hide'].label,
  },
  {
    icon: <ExpandRoundedIcon />,
    name: 'Expand/collapse toolbar',
    shortcut: SHORTCUTS['toolbar-expand-collapse'].label,
  },
  {
    icon: <VideocamRoundedIcon />,
    name: 'Show/hide webcam',
    shortcut: SHORTCUTS['webcam-show-hide'].label,
  },
  {
    icon: <PenIcon />,
    name: 'Use pen',
    shortcut: SHORTCUTS['pen-tool'].label,
  },
  {
    icon: <RectangleIcon />,
    name: 'Use rectangle tool',
    shortcut: SHORTCUTS['rectangle-tool'].label,
  },
  {
    icon: <EraserIcon />,
    name: 'Use eraser',
    shortcut: SHORTCUTS['eraser-tool'].label,
  },
  {
    icon: <EmojiEmotionsRoundedIcon sx={{ color: colors.gray['800'] }} />,
    name: 'Use stickers',
    shortcut: SHORTCUTS['stickers-tool'].label,
  },
  {
    icon: <ClearAllIcon />,
    name: 'Wipe screen',
    shortcut: SHORTCUTS['clear-canvas'].label,
  },
  {
    icon: <Cursor />,
    name: 'Use default mouse',
    shortcut: SHORTCUTS['classic-cursor'].label,
  },
  {
    icon: <Spotlight />,
    name: 'Use spotlight mouse',
    shortcut: SHORTCUTS['focus-cursor'].label,
  },
  {
    icon: <Highlight />,
    name: 'Use highlight clicks mouse',
    shortcut: SHORTCUTS['clicks-cursor'].label,
  },
  {
    icon: <Fireworks />,
    name: 'Use fireworks mouse',
    shortcut: SHORTCUTS['fireworks-cursor'].label,
  },
  {
    icon: <CloseRoundedIcon />,
    name: 'Exit tool and return to main toolbar',
    shortcut: `${SHORTCUTS['close-tool'].label} while using other tools; this will also select the last saved mouse`,
  },
];

export default function KeyboardShortcutSettings() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <Section>
      <SectionHeader>Keyboard Shortcuts</SectionHeader>
      <Link
        variant="subtitle2"
        href="chrome://extensions/shortcuts"
        onClick={() => {
          chrome.tabs.create({ url: 'chrome://extensions/shortcuts' });
        }}
      >
        Configure recording shortcuts
      </Link>
      <Link
        variant="subtitle2"
        sx={{ cursor: 'pointer' }}
        onClick={() => setIsOpen(true)}
      >
        View drawing tools shortcuts
      </Link>
      <Dialog open={isOpen} onClose={() => setIsOpen(false)}>
        <DialogTitle>Drawing Tools Shortcuts</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Shortcuts for drawing tools in tab recording mode.
          </DialogContentText>
          {DRAWING_SHORTCUTS.map(({ icon, name, shortcut }, i) => (
            <Box
              key={`${name}-${i}`}
              width="100%"
              display="flex"
              alignItems="center"
              gap="16px"
              padding="12px 16px"
            >
              {icon}
              <Box display="flex" flexDirection="column" gap="4px">
                <Box component="h3">{name}</Box>
                <Box component="span" color={colors.textSecondary}>
                  {shortcut}
                </Box>
              </Box>
            </Box>
          ))}
        </DialogContent>
      </Dialog>
    </Section>
  );
}
