import { observer } from 'mobx-react-lite';
import { useDrawingState } from '../../state/context/useDrawingToolsState.hook';
import Box from '@mui/material/Box';
import { ToolButton } from '../utility/ToolButton';
import { ColorSlider } from '../utility/ColorSlider/ColorSlider';
import { FadeTimer } from '../utility/FadeTimer';
import { PenIcon } from '../icons/PenIcon';
import { SHORTCUTS } from '../../consts/shortcuts';

interface PenToolsProps {
  isActive?: boolean;
  isExpanded?: boolean;
  onSelect?: () => void;
}

export const PenTools = observer(
  ({ isActive, isExpanded, onSelect = () => {} }: PenToolsProps) => {
    if (!isActive && !isExpanded) return null;

    const { color, setColor } = useDrawingState();

    const handleColorChange = (hslColor: string) => {
      setColor(hslColor);
    };

    return isActive && isExpanded ? (
      <Box
        height="32px"
        display="flex"
        justifyContent="center"
        alignItems="center"
        gap="4px"
        border="1px solid #0000001F"
        borderRadius="16px"
        padding="0 1px"
        boxSizing="border-box"
        sx={{ background: '#EEEEEE' }}
      >
        <ToolButton label="Pen" isSelected>
          <PenIcon />
        </ToolButton>
        <ColorSlider hslColor={color} onColorChange={handleColorChange} />
        <FadeTimer />
      </Box>
    ) : (
      <ToolButton
        data-pendo-event="MV3-clk-pen-tools"
        label={`Pen (${SHORTCUTS['pen-tool'].label})`}
        onClick={onSelect}
        isSelected={isActive}
        isDefault
      >
        <PenIcon />
      </ToolButton>
    );
  },
);
