import { PropsWithChildren, useEffect } from 'react';
import { useAuthStore } from './useAuthStore';
import { useSettingsStore } from './useSettingsStore';
import { useTeleprompterStore } from './useTeleprompterStore';
import { useCountdownStore } from './useCountdownStore';
import { usePendoStore } from './usePendoStore';

export const SyncStoreProvider = ({ children }: PropsWithChildren) => {
  const loadSettingsStore = useSettingsStore((s) => s.loadStore);
  const loadAuthStore = useAuthStore((s) => s.loadStore);
  const loadVideoScriptStore = useTeleprompterStore((s) => s.loadStore);
  const loadCountdownStore = useCountdownStore((s) => s.loadStore);
  const loadPendoStore = usePendoStore((s) => s.loadStore);
  const isQuickRecordStoreLoaded = useSettingsStore((s) => s.isStoreLoaded);
  const isAuthStoreLoaded = useAuthStore((s) => s.isStoreLoaded);
  const isVideoScriptStoreLoaded = useTeleprompterStore((s) => s.isStoreLoaded);
  const isCountdownStoreLoaded = useCountdownStore((s) => s.isStoreLoaded);
  const isPendoStoreLoaded = usePendoStore((s) => s.isStoreLoaded);

  useEffect(() => {
    loadSettingsStore();
    loadAuthStore();
    loadVideoScriptStore();
    loadCountdownStore();
    loadPendoStore();
  }, []);

  if (
    !isQuickRecordStoreLoaded ||
    !isAuthStoreLoaded ||
    !isVideoScriptStoreLoaded ||
    !isCountdownStoreLoaded ||
    !isPendoStoreLoaded
  )
    return null;
  return <>{children}</>;
};
