import React from 'react';
import { Instance, types } from 'mobx-state-tree';

import { DrawingState } from '../DrawingState.mst';
import { CursorModeState } from '../CursorModeState.mst';
import { EraserState } from '../EraserState.mst';
import { PenState } from '../PenState.mst';
import { RectangleState } from '../RectangleState.mst';
import { StickersState } from '../StickersState.mst';

export const DrawingToolsStore = types.model('DrawingToolsStore', {
  cursorMode: types.optional(CursorModeState, {}),
  drawing: types.optional(DrawingState, {}),
  eraser: types.optional(EraserState, {}),
  pen: types.optional(PenState, {}),
  rectangle: types.optional(RectangleState, {}),
  stickers: types.optional(StickersState, {}),
});

export const makeBlankContext = () => DrawingToolsStore.create();

export const DrawingToolsContext = React.createContext<
  Instance<typeof DrawingToolsStore>
>(makeBlankContext());
