import { useMemo } from 'react';
import styles from './Options.styles';
import Typography from '@mui/material/Typography';
import Select, { type SelectChangeEvent } from '@mui/material/Select';
import MenuItem from '@mui/material/MenuItem';

export type Item = {
  label: string;
  value: string | number;
};

interface SelectSettingProps {
  items?: Array<Item | string>;
  selectedItem?: string | number;
  onChange?: (newSelectedItem: string | number) => void;
  title?: string;
  caption?: string;
  disabled?: boolean;
}

export const SelectSetting = ({
  items = [],
  selectedItem,
  onChange = () => {},
  title = '',
  caption = '',
  disabled = false,
}: SelectSettingProps) => {
  const currentItems = useMemo(() => {
    if (items.length === 0) return items;
    if (typeof items.at(0) !== 'string') return items;
    return items.map((item) => ({ label: item, value: item }));
  }, [items]) as Array<Item>;

  const handleChange = (event: SelectChangeEvent<string | number>) => {
    onChange(event.target.value ?? '');
  };

  return (
    <label css={styles.select}>
      <div css={styles.label}>
        <Typography variant="h3" sx={{ fontSize: '1.25rem', fontWeight: 400 }}>
          {title}
        </Typography>
        {caption && (
          <Typography
            variant="caption"
            sx={{ fontSize: '0.875rem', fontWeight: 400, mt: '4px' }}
          >
            {caption}
          </Typography>
        )}
      </div>
      <Select disabled={disabled} value={selectedItem} onChange={handleChange}>
        {currentItems.map((item) => (
          <MenuItem key={item.value} value={item.value}>
            {item.label}
          </MenuItem>
        ))}
      </Select>
    </label>
  );
};
