import { useState } from 'react';

import { useEvent } from '../../../hooks/useEvent.hook';
import { styled } from '../../../styled';

interface ContainerCssProperties extends React.CSSProperties {
  '--shade'?: string;
  '--size'?: string;
  '--clientX': `${number}`;
  '--clientY': `${number}`;
}

const Container = styled<ContainerCssProperties>('div', {
  '--shade': 'rgba(0, 0, 0, 0.3)',
  '--size': '200px',
  '--clientX': '0',
  '--clientY': '0',

  pointerEvents: 'none',
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100vw',
  height: '100vh',
});

const North = styled('div', {
  backgroundColor: 'var(--shade)',
  position: 'absolute',
  width: '100%',
  height: 'calc(1px * var(--clientY) - var(--size) / 2)',
});

const South = styled('div', {
  backgroundColor: 'var(--shade)',
  position: 'absolute',
  width: '100%',
  bottom: 0,
  height: 'calc(100% - var(--size) - (1px * var(--clientY) - var(--size) / 2))',
});

const East = styled('div', {
  backgroundColor: 'var(--shade)',
  position: 'absolute',
  right: 0,
  top: 'calc(1px * var(--clientY) - var(--size) / 2)',
  height: 'var(--size)',
  width: 'calc(100% - var(--size) - (1px * var(--clientX) - var(--size) / 2))',
});

const West = styled('div', {
  backgroundColor: 'var(--shade)',
  position: 'absolute',
  top: 'calc(1px * var(--clientY) - var(--size) / 2)',
  height: 'var(--size)',
  width: 'calc(1px * var(--clientX) - var(--size) / 2)',
});

const Spotlight = styled('div', {
  position: 'absolute',
  left: 'calc(1px * var(--clientX) - var(--size) / 2)',
  top: 'calc(1px * var(--clientY) - var(--size) / 2)',
  width: 'var(--size)',
  height: 'var(--size)',
  backgroundImage: `radial-gradient(
    circle,
    transparent 50%,
    rgba(0, 0, 0, 0.3) 65%
  )`,
});

export const Focus = () => {
  const windowRef = { current: window };
  const [x, setX] = useState<`${number}`>('0');
  const [y, setY] = useState<`${number}`>('0');

  useEvent(windowRef, 'pointermove', (event) => {
    setX(`${event.clientX}`);
    setY(`${event.clientY}`);
  });

  return (
    <Container
      data-testid="FocusContainer"
      style={{
        '--clientX': x,
        '--clientY': y,
      }}
    >
      <North />
      <West />
      <Spotlight />
      <East />
      <South />
    </Container>
  );
};
