import { getParent, types } from 'mobx-state-tree';
import { DrawingState } from '../DrawingState.mst';
import { Point2D } from './Point2D.mst';
import { Point } from '../../components/tools/math';
import { AnchorModel } from '../AnchorModel.mst';

export const PenPathDrawing = types
  .model('PenPath', {
    anchorModel: types.optional(AnchorModel, { anchor: null }),
    points: types.array(Point2D),
    size: types.number,
    color: types.string,
  })
  .actions((self) => {
    return {
      moveTo(x: number, y: number) {
        self.points.push({ x, y });
        self.anchorModel.recalculateAnchor(new Point(x, y));
      },
      drawTo(ctx: CanvasRenderingContext2D) {
        const clippingBox = self.anchorModel.getCurrentAnchorBox();
        if (!clippingBox) return;

        ctx.save();
        const parentContext = getParent(self, 2);
        if (DrawingState.is(parentContext)) {
          ctx.globalAlpha = parentContext.fade;
        }
        ctx.lineCap = 'round';
        ctx.strokeStyle = self.color;
        ctx.lineWidth = self.size;
        ctx.beginPath();
        ctx.stroke(this.computePath());
        ctx.restore();
        ctx.globalAlpha = 1;
      },
      computePath() {
        const path = new Path2D();
        const transform = self.anchorModel.transformToView();
        const transformedPoints = self.points.map((p) =>
          transform.apply(new Point(p.x, p.y)),
        );
        if (transformedPoints.length === 1) {
          path.arc(
            transformedPoints[0].x,
            transformedPoints[0].y,
            1,
            0,
            2 * Math.PI,
          );
        } else {
          for (let i = 0; i < transformedPoints.length - 1; ++i) {
            const point = new Point(
              transformedPoints[i].x,
              transformedPoints[i].y,
            );
            const next = new Point(
              transformedPoints[i + 1].x,
              transformedPoints[i + 1].y,
            );
            path.moveTo(...point.toPair());
            path.lineTo(...next.toPair());
          }
        }
        return path;
      },
    };
  });
