import Switch from '@mui/material/Switch';
import { observer } from 'mobx-react-lite';
import styles from './Switch.styles';

export const DisabledVideoSwitch = observer(
  ({ checked = false }: { checked?: boolean }) => {
    return (
      <Switch
        aria-label="camera toggle"
        disabled
        checked={checked}
        css={styles('video', { isEnabled: false })}
        sx={{ opacity: 0.6 }}
      />
    );
  },
);
