import { useState } from 'react';
import { observer } from 'mobx-react-lite';
import VideocamRoundedIcon from '@mui/icons-material/VideocamRounded';
import VideocamOffRoundedIcon from '@mui/icons-material/VideocamOffRounded';
import Tooltip from '@mui/material/Tooltip';
import IconButton from '@mui/material/IconButton';
import { PopperProps } from '@mui/material';
import { useControllerState } from '@castify/record-mv3/record-components';
import styles from './WebcamControls.styles';
import { SHORTCUTS } from '../../../consts/shortcuts';

export const WebcamControls = observer(() => {
  const { recordingSettings } = useControllerState();
  const [isHovered, setIsHovered] = useState(false);

  const handleMouseEnter = () => {
    setIsHovered(true);
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
  };

  const popperProps: Partial<PopperProps> = {
    disablePortal: true,
  };

  return (
    <Tooltip
      title={`Turn ${recordingSettings.useVideoDevice ? 'Off' : 'On'} Webcam (${
        SHORTCUTS['webcam-show-hide'].label
      })`}
      placement="top"
      PopperProps={popperProps}
    >
      <IconButton
        onClick={() =>
          recordingSettings?.setUseVideoDevice(
            !recordingSettings.useVideoDevice,
          )
        }
        sx={{ width: '28px', height: '28px' }}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        aria-label="webcam toggle"
      >
        {recordingSettings.useVideoDevice ? (
          isHovered ? (
            <VideocamOffRoundedIcon />
          ) : (
            <VideocamRoundedIcon color="primary" />
          )
        ) : (
          <VideocamRoundedIcon color={isHovered ? 'primary' : undefined} />
        )}
        <div
          css={styles.onIndicator({
            isVisible: recordingSettings.useVideoDevice,
          })}
        />
      </IconButton>
    </Tooltip>
  );
});
