import { clone, IAnyStateTreeNode, Instance, types } from 'mobx-state-tree';
import { EraserPathDrawing } from './drawing-elements/EraserPathDrawing.mst';
import { PenPathDrawing } from './drawing-elements/PenPathDrawing.mst';
import { RectangleDrawing } from './drawing-elements/RectangleDrawing.mst';
import { StickerDrawing } from './drawing-elements/StickerDrawing.mst';

export const MODES = {
  CURSOR: 'CURSOR',
  RECTANGLE: 'RECTANGLE',
  PEN: 'PEN',
  STICKER: 'STICKER',
  ERASER: 'ERASER',
  TEXT: 'TEXT',
  BLUR: 'BLUR',
  NONE: 'NONE',
};

export const DrawingState = types
  .model('DrawingState', {
    mode: types.optional(types.string, MODES.CURSOR),
    isExpanded: types.optional(types.boolean, true),
    drawing: types.array(
      types.union(
        PenPathDrawing,
        RectangleDrawing,
        StickerDrawing,
        EraserPathDrawing,
      ),
    ),
    //percentage representation of a fade 1 = 100 visible
    fade: types.optional(types.number, 1),
    //how long to wait for a fade
    fadeTimer: types.optional(types.number, 0),
    color: types.optional(types.string, 'red'),
    size: types.optional(types.number, 8),
  })
  .views((self) => {
    return {
      get fadeTimerDurations() {
        return {
          timeToFade: self.fadeTimer * 0.75,
          fadeDuration: 2000,
        };
      },
      get timeToDisappear() {
        return (
          this.fadeTimerDurations.timeToFade +
          this.fadeTimerDurations.fadeDuration
        );
      },
      isDrawingMode() {
        return (
          self.mode === MODES.PEN ||
          self.mode === MODES.RECTANGLE ||
          self.mode === MODES.ERASER
        );
      },
      isStickerMode() {
        return self.mode === MODES.STICKER;
      },
    };
  })
  .actions((self) => {
    return {
      clearDrawing() {
        self.drawing.clear();
      },
      addElement(element: IAnyStateTreeNode) {
        self.drawing.push(clone(element));
      },
      updateLastElement(element: IAnyStateTreeNode) {
        self.drawing.pop();
        self.drawing.push(clone(element));
      },
      setColor(color: string) {
        self.color = color;
      },
      setSize(size: number) {
        self.size = size;
      },
      resetFade() {
        self.fade = 1;
      },
      setFade(newFade: number) {
        self.fade = newFade;
      },
      setFadeTimer(newFadeTimer: number) {
        self.fadeTimer = newFadeTimer;
      },
      setMode(newMode: string) {
        self.mode = newMode;
      },
      setIsExpanded(isExpanded: boolean) {
        self.isExpanded = isExpanded;
      },
    };
  });

export type IDrawingState = Instance<typeof DrawingState>;
