import { observer } from 'mobx-react-lite';
import { ToolButton } from '../utility/ToolButton';
import { EraserIcon } from '../icons/EraserIcon';
import { SHORTCUTS } from '../../consts/shortcuts';

interface EraserToolsProps {
  isActive?: boolean;
  isExpanded?: boolean;
  onSelect?: () => void;
}

export const EraserTools = observer(
  ({ isActive, isExpanded, onSelect = () => {} }: EraserToolsProps) => {
    if (!isActive && !isExpanded) return null;

    return (
      <ToolButton
        data-pendo-event="MV3-clk-eraser"
        label={`Eraser (${SHORTCUTS['eraser-tool'].label})`}
        onClick={onSelect}
        isSelected={isActive}
        isDefault
      >
        <EraserIcon />
      </ToolButton>
    );
  },
);
