import { useRef, useState } from 'react';
import { OPACITY_MARGIN } from '../DrawingTools.styles';
import { useEvent } from './useEvent.hook';

const OFFSET_X = 14 + OPACITY_MARGIN;
const OFFSET_Y = 22 + OPACITY_MARGIN;

export const useDragging = () => {
  const windowRef = useRef(window);
  const draggingRef = useRef<HTMLDivElement>(null);
  const dragHandlerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const getDraggingPosition = (x: number, y: number) => {
    if (!draggingRef.current || !dragHandlerRef.current) return { x, y };
    const { width: draggingWidth, height: draggingHeight } =
      draggingRef.current.getBoundingClientRect();

    const windowHeight = window.innerHeight;
    const windowWidth = window.innerWidth;
    const windowBounds = {
      top: 0,
      right: windowWidth - draggingWidth,
      bottom: windowHeight - draggingHeight,
      left: 0,
    };

    const offsetX = x - OFFSET_X;
    const offsetY = y - OFFSET_Y;

    return {
      x: Math.min(
        Math.max(offsetX, windowBounds.left - OPACITY_MARGIN),
        windowBounds.right + OPACITY_MARGIN,
      ),
      y: Math.min(
        Math.max(offsetY, windowBounds.top - OPACITY_MARGIN),
        windowBounds.bottom + OPACITY_MARGIN,
      ),
    };
  };

  useEvent(dragHandlerRef, 'pointerdown', () => {
    setIsDragging(true);
    if (!dragHandlerRef.current) return;
    dragHandlerRef.current.style.width = '1000px';
    dragHandlerRef.current.style.height = '1000px';
    dragHandlerRef.current.style.userSelect = 'none';
    dragHandlerRef.current.style.cursor = 'grabbing';
  });

  useEvent(dragHandlerRef, 'pointermove', (event) => {
    if (!isDragging || !draggingRef.current) return;
    const { clientX, clientY } = event;
    const { x, y } = getDraggingPosition(clientX, clientY);
    draggingRef.current.style.left = 'auto';
    draggingRef.current.style.bottom = 'auto';
    draggingRef.current.style.transform = `translate(${x}px, ${y}px)`;
  });

  const resetDragHandlerCSS = () => {
    if (!dragHandlerRef.current) return;
    dragHandlerRef.current.style.width = '100%';
    dragHandlerRef.current.style.height = '100%';
    dragHandlerRef.current.style.cursor = 'grab';
  };

  useEvent(dragHandlerRef, 'pointerup', () => {
    setIsDragging(false);
    resetDragHandlerCSS();
  });

  useEvent(windowRef, 'pointercancel', () => {
    setIsDragging(false);
    resetDragHandlerCSS();
  });

  useEvent(windowRef, 'mouseup', () => {
    setIsDragging(false);
    resetDragHandlerCSS();
  });

  return {
    draggingRef,
    dragHandlerRef,
  };
};
