import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { FabricObject } from 'fabric';
import { Point } from '../../components/tools/math';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';

const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'getElementFromIframe',
    buildId: currentVersion,
  },
);

export const getElementUnderFabricObject = (fabricObject: FabricObject) => {
  const { left, top } = fabricObject.getBoundingRect();
  const point = new Point(left, top);
  return elementAt(point);
};

const elementAt = (point: Point): Element | null => {
  const pair = point.toPair();
  const elements = document.elementsFromPoint(...pair) || [];

  let el: Element | null =
    elements.find(
      (element) =>
        document.querySelector('castify-shadow-container') !== element,
    ) ?? null;

  let best: Element | null = el;

  while (el && el.shadowRoot) {
    const next = el.shadowRoot.elementFromPoint(...pair);
    if (next === el) break; // On M67 elementFromPoint returns element itself.
    el = next;
    if (el) best = el;
  }

  // if best element is an iframe, get the best element from the iframe
  if (best?.tagName === 'IFRAME') {
    const iframeElement = getElementFromIframe(
      best as HTMLIFrameElement,
      pair[0],
      pair[1],
    );
    if (iframeElement) best = iframeElement;
  }

  return best;
};

const getElementFromIframe = (
  iframe: HTMLIFrameElement,
  x: number,
  y: number,
): Element | null => {
  try {
    const iframeRect = iframe.getBoundingClientRect();
    const iframeDocument = iframe.contentDocument;
    const iframeWindow = iframe.contentWindow;

    if (iframeDocument || iframeWindow?.document) {
      const iframePoint = {
        x: x - iframeRect.left,
        y: y - iframeRect.top,
      };

      const iframeElements =
        iframeDocument?.elementsFromPoint(iframePoint.x, iframePoint.y) || [];
      return iframeElements.length ? iframeElements[0] : null;
    }
  } catch (err) {
    logger.warn('Cross-origin iframe detected, cannot access contents.', err);
  }

  return null;
};
