import { PropsWithChildren } from 'react';
import IconButton from '@mui/material/IconButton';
import Tooltip from '@mui/material/Tooltip';
import Box from '@mui/material/Box';

interface ToolButtonProps {
  label?: string;
  isSelected?: boolean;
  isDefault?: boolean;
  disabled?: boolean;
  onClick?: () => void;
}

export const ToolButton = ({
  label = '',
  isSelected,
  isDefault,
  disabled,
  onClick = () => {},
  children,
  ...rest
}: PropsWithChildren<ToolButtonProps>) => {
  return (
    <Tooltip
      title={label}
      placement="top"
      PopperProps={{ disablePortal: true }}
    >
      {/* Box needed to catch Tooltip pointer events when Button is disabled. */}
      <Box>
        <IconButton
          {...rest}
          onClick={onClick}
          disabled={disabled}
          sx={{
            width: '28px',
            height: '28px',
            background: isSelected ? '#4242424D' : 'initial',
            pointerEvents: isSelected && !isDefault ? 'none' : 'initial',
            transition: 'background 0.3s ease-in-out',
            marginLeft: isDefault ? '2px' : '0',
            '&:hover': {
              background: isSelected && isDefault ? '#4242424D' : 'default',
            },
          }}
        >
          <Box display="flex" justifyContent="center" alignItems="center">
            {children}
          </Box>
        </IconButton>
      </Box>
    </Tooltip>
  );
};
