import { useEffect, useRef } from 'react';
import { TPointerEventInfo, Textbox } from 'fabric';
import {
  CustomFabricObject,
  useCanvasState,
  getElementUnderFabricObject,
  useCanvasCursor,
  useFabricCanvas,
  removeActiveObject,
} from '../../../state/canvas';

const PLACEHOLDER_TEXT = 'Start Typing...';
const PLACEHOLDER_COLOR = '#4F4F4F4D';
const TEXT_COLOR = '#212121';
const DEFAULT_SELECTION_COLOR = 'rgba(17,119,255,0.3)';

const waitForFabricTextarea = (
  timeout = 1000,
): Promise<HTMLTextAreaElement | null> => {
  return new Promise((resolve) => {
    const start = Date.now();

    const check = () => {
      const textarea = document.querySelector(
        'textarea[data-fabric="textarea"]',
      ) as HTMLTextAreaElement | null;
      if (textarea) return resolve(textarea);
      if (Date.now() - start > timeout) return resolve(null);
      requestAnimationFrame(check);
    };
    check();
  });
};

const ensureTextareaInFullscreen = async () => {
  const textarea = await waitForFabricTextarea();
  const fullscreenEl = document.fullscreenElement;

  if (textarea && fullscreenEl && !fullscreenEl.contains(textarea)) {
    fullscreenEl.appendChild(textarea);
  }

  if (!textarea) return;
  textarea.focus();
  textarea.style.zIndex = '999999999';
  textarea.style.position = 'absolute';
};

export const TextMode = () => {
  const [canvas, addObject, updateAnchorById] = useCanvasState((s) => [
    s.canvas,
    s.addObject,
    s.updateAnchorById,
  ]);
  const activeTextRef = useRef<Textbox | null>(null);

  useFabricCanvas();
  useCanvasCursor({ default: 'text', hover: 'pointer', move: 'move' });

  useEffect(() => {
    if (!canvas) return;

    const handleMouseDown = async (
      event: TPointerEventInfo<MouseEvent | TouchEvent>,
    ) => {
      if (activeTextRef.current) return;
      const target = canvas.findTarget(event.e);
      if (target) return;

      const pointer = canvas.getViewportPoint(event.e);
      const textBox = new Textbox(PLACEHOLDER_TEXT, {
        left: pointer.x,
        top: pointer.y,
        width: 200,
        fontSize: 20,
        fontFamily: 'Fellix',
        fontWeight: '700',
        fill: PLACEHOLDER_COLOR,
        textAlign: 'left',
        lineHeight: 1.5,
        padding: 12,
        borderColor: '#FFC107',
        editingBorderColor: '#FFC107',
        borderDashArray: [5, 5],
        borderScaleFactor: 2,
        cornerColor: '#FFC107',
        cornerStyle: 'circle',
        cornerSize: 14,
        transparentCorners: false,
        borderOpacityWhenMoving: 1,
        editable: true,
        hasControls: true,
      });

      textBox.on('mousedown', () => {
        if (textBox.text === PLACEHOLDER_TEXT) {
          textBox.enterEditing();
        }
      });

      textBox.on('editing:entered', async () => {
        await ensureTextareaInFullscreen();
        activeTextRef.current = textBox;
        if (textBox.text === PLACEHOLDER_TEXT) {
          textBox.set('selectionColor', 'transparent');
          textBox.selectAll();
        }
      });

      textBox.on('changed', () => {
        if (textBox.selectionColor === 'transparent') {
          textBox.set('selectionColor', DEFAULT_SELECTION_COLOR);
          textBox.set('fill', TEXT_COLOR);
        }
      });

      textBox.on('editing:exited', () => {
        if (textBox.text === PLACEHOLDER_TEXT) {
          removeActiveObject();
        }
        setTimeout(() => {
          activeTextRef.current = null;
        }, 0);
      });

      textBox.on('modified', () => {
        const customTextBox = textBox as CustomFabricObject;
        if (!customTextBox.id) return;
        updateAnchorById(
          customTextBox.id,
          getElementUnderFabricObject(textBox),
        );
      });

      addObject(textBox, getElementUnderFabricObject(textBox));
      canvas.setActiveObject(textBox);
      textBox.enterEditing();
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Delete' || event.key === 'Backspace') {
        const activeObject = canvas.getActiveObject();
        if (activeObject) {
          if (activeObject instanceof Textbox && activeObject.isEditing) return;
          removeActiveObject();
        }
      }
    };

    canvas.on('mouse:down', handleMouseDown);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      canvas.off('mouse:down', handleMouseDown);
      window.removeEventListener('keydown', handleKeyDown);
      canvas.discardActiveObject();
      canvas.renderAll();
    };
  }, [canvas]);

  return null;
};
